SURFACE_GRAVITY = {
    "mercury": 3.7,
    "venus": 8.87,
    "earth": 9.81,
    "mars": 3.7,
    "jupiter": 24.79,
    "saturn": 10.44,
    "uranus": 8.87,
    "neptune": 11.15,
    "pluto": 0.62,
}

ORDERED_BODIES = [
    "mercury",
    "venus",
    "earth",
    "mars",
    "jupiter",
    "saturn",
    "uranus",
    "neptune",
    "pluto",
]


def gravity(planet):
    if not isinstance(planet, str):
        return 0
    return SURFACE_GRAVITY.get(planet.strip().lower(), 0)


def weight_on(planet, mass_kg):
    return mass_kg * gravity(planet)


def relative_to_earth(planet):
    g = gravity(planet)
    if g == 0:
        return 0
    return g / SURFACE_GRAVITY["earth"]


def describe(planet, mass_kg):
    return {
        "planet": planet.strip().title(),
        "gravity": gravity(planet),
        "weight_n": round(weight_on(planet, mass_kg), 2),
        "earth_ratio": round(relative_to_earth(planet), 3),
    }


def format_row(record):
    return "{:<9} {:>6} {:>10} {:>7}".format(
        record["planet"],
        record["gravity"],
        record["weight_n"],
        record["earth_ratio"],
    )


def build_report(mass_kg, bodies=None):
    names = bodies if bodies is not None else ORDERED_BODIES
    lines = [
        "{:<9} {:>6} {:>10} {:>7}".format("Body", "g", "Weight", "xEarth"),
        "-" * 35,
    ]
    for name in names:
        lines.append(format_row(describe(name, mass_kg)))
    return "\n".join(lines)


def main():
    print(gravity("mars"))
    print(build_report(70.0))
    for query in [
        "EARTH",
        "  Jupiter ",
        "Vulcan",
    ]:
        print("{!r} -> {}".format(query, gravity(query)))


if __name__ == "__main__":
    main()

