VALUE_SYMBOLS = [
    (1000, "M"),
    (900, "CM"),
    (500, "D"),
    (400, "CD"),
    (100, "C"),
    (90, "XC"),
    (50, "L"),
    (40, "XL"),
    (10, "X"),
    (9, "IX"),
    (5, "V"),
    (4, "IV"),
    (1, "I"),
]

ROMAN_VALUES = {
    "M": 1000,
    "D": 500,
    "C": 100,
    "L": 50,
    "X": 10,
    "V": 5,
    "I": 1,
}


def romanize(number):
    if not isinstance(number, int) or isinstance(number, bool):
        raise TypeError(
            "romanize() expects an integer, got {0}".format(type(number).__name__),
        )
    if not 1 <= number <= 3999:
        raise ValueError(
            "number must be between 1 and 3999, got {0}".format(number),
        )
    remaining = number
    letters = []
    for value, symbol in VALUE_SYMBOLS:
        while remaining >= value:
            letters.append(symbol)
            remaining -= value
    return "".join(letters)


def deromanize(numeral):
    text = numeral.strip().upper()
    if not text:
        raise ValueError("numeral must contain at least one letter")
    total = 0
    previous = 0
    for char in reversed(text):
        if char not in ROMAN_VALUES:
            raise ValueError("invalid roman letter: {0!r}".format(char))
        value = ROMAN_VALUES[char]
        if value < previous:
            total -= value
        else:
            total += value
            previous = value
    return total


def format_table(numbers):
    rows = [
        ("DECIMAL", "ROMAN"),
    ]
    rows.extend((str(number), romanize(number)) for number in numbers)
    width = max(len(decimal) for decimal, _ in rows)
    return "\n".join("{0:>{2}}  {1}".format(decimal, roman, width) for decimal, roman in rows)


def main():
    examples = [
        4,
        9,
        14,
        40,
        1066,
        1987,
        2024,
        3999,
    ]
    print(format_table(examples))
    landmarks = {
        "first olympiad": 776,
        "battle of hastings": 1066,
        "moon landing": 1969,
    }
    print()
    for name, year in landmarks.items():
        print("{0}: {1}".format(name, romanize(year)))
    print()
    for text in ["MCMXCIV", "MMXXV", "XLII"]:
        print("{0} = {1}".format(text, deromanize(text)))


if __name__ == "__main__":
    main()

