import sys

DENOMINATIONS = [
    ("hundred", 10000),
    ("fifty", 5000),
    ("twenty", 2000),
    ("ten", 1000),
    ("five", 500),
    ("one", 100),
    ("quarter", 25),
    ("dime", 10),
    ("nickel", 5),
    ("penny", 1),
]

IRREGULAR_PLURALS = {
    "penny": "pennies",
    "twenty": "twenties",
    "fifty": "fifties",
}


def to_cents(amount):
    if isinstance(amount, bool) or not isinstance(amount, (int, float)):
        raise TypeError("amount must be a number, got {!r}".format(amount))
    if amount < 0:
        raise ValueError(
            "amount must not be negative: {!r}".format(amount),
        )
    return int(round(amount * 100))


def plural(name, count):
    if count == 1:
        return name
    return IRREGULAR_PLURALS.get(name, name + "s")


def change(amount):
    remaining = to_cents(amount)
    counts = []
    for _name, value in DENOMINATIONS:
        counts.append(remaining // value)
        remaining %= value
    return counts


def summarize(amount):
    counts = change(amount)
    return {
        "amount": amount,
        "counts": counts,
        "pieces": sum(counts),
        "labels": [
            (count, plural(name, count))
            for (name, _value), count in zip(DENOMINATIONS, counts)
            if count
        ],
    }


def format_report(amount):
    info = summarize(amount)
    lines = [
        "Amount: ${:,.2f}".format(info["amount"]),
        "Counts: {}".format(info["counts"]),
        "Pieces: {}".format(info["pieces"]),
    ]
    for count, label in info["labels"]:
        lines.append("  {:>3} {}".format(count, label))
    return "\n".join(lines)


def main(argv):
    if len(argv) < 2:
        print("usage: {} AMOUNT [AMOUNT ...]".format(argv[0]), file=sys.stderr)
        return 1
    for text in argv[1:]:
        print(format_report(float(text)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

