def portion_macros(ingredient):
    entry = lookup(ingredient)
    share = entry["grams"] / 100.0
    return {
        "protein": entry["protein"] * share,
        "carbs": entry["carbs"] * share,
        "fat": entry["fat"] * share,
    }


def macro_totals(recipe):
