FILES = "abcdefgh"
RANKS = "12345678"

ORTHOGONAL = [
    (1, 0),
    (-1, 0),
    (0, 1),
    (0, -1),
]

DIAGONAL = [
    (1, 1),
    (1, -1),
    (-1, 1),
    (-1, -1),
]

KNIGHT_VECTORS = [
    (1, 2),
    (2, 1),
    (2, -1),
    (1, -2),
    (-1, -2),
    (-2, -1),
    (-2, 1),
    (-1, 2),
]

DIRECTIONS = {
    "king": ORTHOGONAL + DIAGONAL,
    "queen": ORTHOGONAL + DIAGONAL,
    "rook": list(ORTHOGONAL),
    "bishop": list(DIAGONAL),
    "knight": list(KNIGHT_VECTORS),
}

SLIDING_PIECES = frozenset({
    "queen",
    "rook",
    "bishop",
})


def parse_square(position):
    text = position.strip().lower()
    if len(text) != 2 or text[0] not in FILES or text[1] not in RANKS:
        raise ValueError("not a board coordinate: {0!r}".format(position))
    return FILES.index(text[0]), RANKS.index(text[1])


def format_square(file_index, rank_index):
    return FILES[file_index] + RANKS[rank_index]


def moves(piece, position):
    name = piece.strip().lower()
    if name not in DIRECTIONS:
        raise ValueError("unknown piece: {0!r}".format(piece))
    file_index, rank_index = parse_square(position)
    reach = 7 if name in SLIDING_PIECES else 1
    destinations = []
    for delta_file, delta_rank in DIRECTIONS[name]:
        for step in range(1, reach + 1):
            target_file = file_index + delta_file * step
            target_rank = rank_index + delta_rank * step
            if not (0 <= target_file < 8 and 0 <= target_rank < 8):
                break
            destinations.append(format_square(target_file, target_rank))
    return sorted(destinations)


def describe(piece, position):
    squares = moves(piece, position)
    return "{0} on {1} ({2} moves): {3}".format(
        piece,
        position,
        len(squares),
        " ".join(squares),
    )


def main():
    samples = [
        ("knight", "d4"),
        ("king", "a1"),
        ("rook", "h5"),
        ("bishop", "c1"),
        ("queen", "e4"),
    ]
    for piece, position in samples:
        print(describe(piece, position))


if __name__ == "__main__":
    main()

