ELEMENTS = {
    "hydrogen": (1, "H"),
    "helium": (2, "He"),
    "lithium": (3, "Li"),
    "beryllium": (4, "Be"),
    "boron": (5, "B"),
    "carbon": (6, "C"),
    "nitrogen": (7, "N"),
    "oxygen": (8, "O"),
    "fluorine": (9, "F"),
    "neon": (10, "Ne"),
    "sodium": (11, "Na"),
    "magnesium": (12, "Mg"),
}

CATEGORIES = {
    "nonmetal": (
        "hydrogen",
        "carbon",
        "nitrogen",
        "oxygen",
    ),
    "noble gas": (
        "helium",
        "neon",
    ),
    "alkali metal": (
        "lithium",
        "sodium",
    ),
}


def element(name):
    """Return the (atomic number, chemical symbol) pair for an element name."""
    if not isinstance(name, str):
        raise TypeError("element name must be a string")
    key = name.strip().lower()
    if key not in ELEMENTS:
        raise KeyError("unknown element: {!r}".format(name))
    return ELEMENTS[key]


def category_of(name):
    """Return the broad chemical family of an element, or 'other'."""
    key = name.strip().lower()
    for family, members in CATEGORIES.items():
        if key in members:
            return family
    return "other"


def describe(name):
    """Build a record describing one element."""
    number, symbol = element(name)
    return {
        "name": name.strip().lower(),
        "number": number,
        "symbol": symbol,
        "category": category_of(name),
    }


def format_row(record):
    return "{number:>3}  {symbol:<3} {name:<10} {category}".format(**record)


def report(names):
    records = [describe(name) for name in names]
    records.sort(key=lambda record: record["number"])
    return "\n".join(format_row(record) for record in records)


def main():
    print(element("oxygen"))
    print(report([
        "Oxygen",
        "helium",
        "carbon",
        "sodium",
        "beryllium",
    ]))
    for bad in ("unobtainium", "gold"):
        try:
            element(bad)
        except KeyError as exc:
            print(exc)


if __name__ == "__main__":
    main()

