PROMOTIONS = {
    "welcome": {
        "kind": "percent",
        "value": 10.0,
        "label": "Welcome offer",
    },
    "staff": {
        "kind": "percent",
        "value": 25.0,
        "label": "Staff discount",
    },
    "wholesale": {
        "kind": "percent",
        "value": 15.0,
        "label": "Wholesale rate",
    },
    "clearance": {
        "kind": "percent",
        "value": 40.0,
        "label": "Clearance event",
    },
    "holiday": {
        "kind": "flat",
        "value": 20.0,
        "label": "Holiday voucher",
    },
    "birthday": {
        "kind": "flat",
        "value": 10.0,
        "label": "Birthday gift",
    },
    "loyalty": {
        "kind": "flat",
        "value": 5.0,
        "label": "Loyalty credit",
    },
}


def normalize(code):
    return str(code).strip().lower()


def apply_promotion(total, rule):
    if rule["kind"] == "percent":
        return total * (1.0 - rule["value"] / 100.0)
    return total - rule["value"]


def checkout(total, codes):
    amount = float(total)
    for code in codes:
        rule = PROMOTIONS.get(normalize(code))
        if rule is None:
            continue
        amount = max(0.0, apply_promotion(amount, rule))
    return float(amount)


def receipt(total, codes):
    lines = [
        "Subtotal: ${:.2f}".format(float(total)),
    ]
    running = float(total)
    for code in codes:
        key = normalize(code)
        rule = PROMOTIONS.get(key)
        if rule is None:
            lines.append("{}: not recognised".format(key))
            continue
        after = max(0.0, apply_promotion(running, rule))
        lines.append("{}: -${:.2f}".format(rule["label"], running - after))
        running = after
    lines.append("Total: ${:.2f}".format(running))
    return "\n".join(lines)


def main():
    carts = [
        (100.0, ["welcome", "birthday"]),
        (250.0, ["staff", "loyalty", "holiday"]),
        (18.0, ["clearance", "holiday", "birthday"]),
        (80.0, ["WholeSale ", "mystery"]),
    ]
    for total, codes in carts:
        print(receipt(total, codes))
        print("checkout -> {}".format(checkout(total, codes)))
        print()


if __name__ == "__main__":
    main()

