MENU = {
    "espresso": {
        "price": 2.00,
        "calories": 5,
        "minutes": 1,
        "category": "beverage",
        "vegan": True,
    },
    "latte": {
        "price": 4.00,
        "calories": 120,
        "minutes": 2,
        "category": "beverage",
        "vegan": False,
    },
    "mocha": {
        "price": 4.50,
        "calories": 200,
        "minutes": 3,
        "category": "beverage",
        "vegan": False,
    },
    "cold brew": {
        "price": 3.00,
        "calories": 10,
        "minutes": 1,
        "category": "beverage",
        "vegan": True,
    },
    "vanilla syrup": {
        "price": 0.50,
        "calories": 40,
        "minutes": 0,
        "category": "additive",
        "vegan": True,
    },
    "caramel": {
        "price": 0.50,
        "calories": 50,
        "minutes": 0,
        "category": "additive",
        "vegan": False,
    },
    "oat milk": {
        "price": 0.75,
        "calories": 30,
        "minutes": 0,
        "category": "additive",
        "vegan": True,
    },
    "whole milk": {
        "price": 0.00,
        "calories": 60,
        "minutes": 0,
        "category": "additive",
        "vegan": False,
    },
}


def normalize(order):
    cleaned = [str(name).strip().lower() for name in order]
    unknown = sorted({name for name in cleaned if name not in MENU})
    if unknown:
        raise ValueError("unknown item(s): " + ", ".join(unknown))
    return cleaned


def bill(order):
    items = normalize(order)
    cost = sum(MENU[name]["price"] for name in items)
    calories = sum(MENU[name]["calories"] for name in items)
    minutes = max((MENU[name]["minutes"] for name in items), default=0)
    return (round(cost, 2), calories, minutes)


def is_vegan(order):
    return all(MENU[name]["vegan"] for name in normalize(order))


def receipt(order):
    items = normalize(order)
    cost, calories, minutes = bill(items)
    lines = ["{0:<14}{1:>6.2f}".format(name, MENU[name]["price"]) for name in items]
    lines.extend([
        "-" * 20,
        "{0:<14}{1:>6.2f}".format("total", cost),
        "{0} kcal, ready in {1} min".format(calories, minutes),
        "vegan: {0}".format("yes" if is_vegan(items) else "no"),
    ])
    return "\n".join(lines)


def main():
    orders = [
        ["espresso", "vanilla syrup", "oat milk"],
        ["mocha", "caramel"],
        ["cold brew", "whole milk", "latte"],
    ]
    for order in orders:
        print(receipt(order))
        print()
    try:
        bill(["flat white"])
    except ValueError as exc:
        print("rejected:", exc)


if __name__ == "__main__":
    main()

