ANIMAL_DB = {
    "lion": {
        "class": "mammal",
        "diet": "carnivore",
        "lifespan": 15,
        "habitat": "savanna",
        "status": "vulnerable",
    },
    "eagle": {
        "class": "bird",
        "diet": "carnivore",
        "lifespan": 20,
        "habitat": "mountains",
        "status": "least concern",
    },
    "frog": {
        "class": "amphibian",
        "diet": "insectivore",
        "lifespan": 5,
        "habitat": "wetlands",
        "status": "endangered",
    },
    "shark": {
        "class": "fish",
        "diet": "carnivore",
        "lifespan": 30,
        "habitat": "ocean",
        "status": "vulnerable",
    },
    "turtle": {
        "class": "reptile",
        "diet": "omnivore",
        "lifespan": 50,
        "habitat": "coastal",
        "status": "endangered",
    },
    "elephant": {
        "class": "mammal",
        "diet": "herbivore",
        "lifespan": 60,
        "habitat": "savanna",
        "status": "endangered",
    },
    "ostrich": {
        "class": "bird",
        "diet": "omnivore",
        "lifespan": 40,
        "habitat": "desert",
        "status": "least concern",
    },
    "salamander": {
        "class": "amphibian",
        "diet": "carnivore",
        "lifespan": 10,
        "habitat": "forest",
        "status": "near threatened",
    },
}


def lookup(name):
    key = name.strip().lower()
    if key not in ANIMAL_DB:
        raise KeyError("unknown animal: {} (known: {})".format(name, ", ".join(sorted(ANIMAL_DB))))
    return ANIMAL_DB[key]


def classify(animals):
    habitats = []
    endangered_present = False
    for name in animals:
        record = lookup(name)
        if record["habitat"] not in habitats:
            habitats.append(record["habitat"])
        if record["status"] == "endangered":
            endangered_present = True
    return habitats, endangered_present


def endangered_names(animals):
    return [name for name in animals if lookup(name)["status"] == "endangered"]


def format_report(label, animals):
    habitats, endangered_present = classify(animals)
    lines = [
        "Survey: {}".format(label),
        "  animals:   {}".format(", ".join(animals) or "none"),
        "  habitats:  {}".format(", ".join(habitats) or "none"),
        "  flagged:   {}".format("yes" if endangered_present else "no"),
        "  species:   {}".format(", ".join(endangered_names(animals)) or "none"),
    ]
    return "\n".join(lines)


def main():
    surveys = [
        ("savanna trip", ["lion", "eagle"]),
        ("wetland walk", ["frog", "salamander", "frog"]),
        ("coast dive", ["shark", "turtle", "ostrich"]),
    ]
    for label, animals in surveys:
        print(format_report(label, animals))
    combined = [name for _, animals in surveys for name in animals]
    print(format_report("all sightings", combined))
    print(classify(["lion", "eagle"]))


if __name__ == "__main__":
    main()

