    }
}


def lookup(consoles):
    years = []
    media = []
    for name in consoles:
        key = name.strip().lower()
        if key not in CONSOLES:
            raise KeyError("unknown console: {0}".format(name))
        record = CONSOLES[key]
        years.append(record["year"])
        if record["media"] not in media:
            media.append(record["media"])
    if not years:
        return (None, [])
    return (min(years), sorted(media))


def describe(name):
    record = CONSOLES[name.strip().lower()]
    return "{flagship} on {bits}-bit {maker} hardware ({media})".format(
        flagship=record["flagship"],
        bits=record["bits"],
        maker=record["maker"],
        media=record["media"]
    )


def report(consoles):
    year, media = lookup(consoles)
    lines = [
        "systems: " + ", ".join(consoles),
        "earliest year: {0}".format(year),
        "media types: " + ", ".join(media)
    ]
    lines.extend(describe(name) for name in consoles)
    return "\n".join(lines)


def main():
