    },
    "linguine": {
        "sauce": "seafood",
        "minutes": 9,
        "region": "liguria",
        "dough": "durum wheat",
        "shape": "flat strands",
    },
    "farfalle": {
        "sauce": "butter sauce",
        "minutes": 12,
        "region": "lombardy",
        "dough": "durum wheat",
        "shape": "bowties",
    },
    "macaroni": {
        "sauce": "cheese sauce",
        "minutes": 8,
        "region": "naples",
        "dough": "durum wheat",
        "shape": "curved tubes",
    },
    "pappardelle": {
        "sauce": "ragu",
        "minutes": 7,
        "region": "tuscany",
        "dough": "egg dough",
        "shape": "wide ribbons",
    },
}


def normalize(name):
    return name.strip().lower()


def lookup(name):
    key = normalize(name)
    if key not in PASTA_GUIDE:
        raise KeyError(
            "unknown pasta {0!r}; known shapes: {1}".format(
                key,
                ", ".join(sorted(PASTA_GUIDE)),
            )
        )
    return PASTA_GUIDE[key]


def match(pastas):
    total = 0
    shapes = []
    for name in pastas:
        entry = lookup(name)
        total += entry["minutes"]
        if entry["shape"] not in shapes:
            shapes.append(entry["shape"])
    return total, shapes


def report(pastas):
    total, shapes = match(pastas)
    lines = [
        "Dinner plan: " + ", ".join(normalize(name) for name in pastas),
        "Total boiling time: {0} minutes".format(total),
        "Shapes: " + ", ".join(shapes),
    ]
    for name in pastas:
        entry = lookup(name)
        lines.append(
            "  {0} -> {1} from {2} ({3})".format(
                normalize(name),
                entry["sauce"],
                entry["region"],
                entry["dough"],
            )
        )
    return "\n".join(lines)


def main():
    plans = [
        ["spaghetti", "penne"],
        ["fusilli", "rigatoni", "linguine"],
        ["farfalle", "macaroni", "pappardelle", "penne"],
    ]
    for plan in plans:
