EQUIPMENT = {
    "warrior": [
        "broadsword",
        "heavy shield",
        "chainmail armor",
        "health potion",
    ],
    "mage": [
        "wooden staff",
        "cloth robe",
        "spellbook",
        "mana potion",
    ],
    "rogue": [
        "dual daggers",
        "leather armor",
        "lockpick set",
        "smoke bomb",
    ],
}

STATS = {
    "warrior": (140, 90, 10),
    "mage": (80, 60, 150),
    "rogue": (100, 130, 40),
}

STAT_NAMES = (
    "health",
    "stamina",
    "mana",
)


def normalize_classes(classes):
    if isinstance(classes, str):
        classes = [classes]
    normalized = []
    for name in classes:
        key = name.strip().lower()
        if key not in EQUIPMENT:
            raise KeyError("unknown character class: {}".format(name))
        normalized.append(key)
    return normalized


def build_character_report(classes):
    report = []
    for key in normalize_classes(classes):
        report.append((
            key,
            list(EQUIPMENT[key]),
            STATS[key],
        ))
    return report


def format_entry(entry):
    class_name, equipment, stats = entry
    stat_text = ", ".join(
        "{}={}".format(label, value)
        for label, value in zip(STAT_NAMES, stats)
    )
    return "{}: {} | {}".format(
        class_name.title(),
        ", ".join(equipment),
        stat_text,
    )


def main():
    party = [
        "mage",
        "Warrior",
        "rogue",
    ]
    for entry in build_character_report(party):
        print(format_entry(entry))
    print(build_character_report("mage"))


if __name__ == "__main__":
    main()

