LENS_CATEGORIES = {
    "wide angle": [
        "landscapes",
        "real estate",
        "architecture",
        "astrophotography",
    ],
    "standard": [
        "portraits",
        "street photography",
        "documentary work",
        "everyday shooting",
    ],
    "telephoto": [
        "sports",
        "wildlife",
        "event photography",
        "aviation",
    ],
    "macro": [
        "insects",
        "flowers",
        "jewelry",
        "abstract close ups",
    ],
}


def normalize(subject):
    return " ".join(str(subject).strip().lower().split())


def find_lens(subject):
    target = normalize(subject)
    for lens_type, subjects in LENS_CATEGORIES.items():
        if target in subjects:
            return lens_type
    return None


def recommend_lenses(subjects):
    pairs = []
    for subject in subjects:
        lens = find_lens(subject)
        pairs.append((
            normalize(subject),
            lens if lens is not None else "unknown",
        ))
    return pairs


def group_by_lens(pairs):
    grouped = {}
    for subject, lens in pairs:
        grouped.setdefault(lens, []).append(subject)
    return grouped


def format_report(pairs):
    lines = []
    for lens, subjects in sorted(group_by_lens(pairs).items()):
        lines.append("{} lens: {}".format(lens, ", ".join(sorted(subjects))))
    return "\n".join(lines)


def main():
