        "wildlife",
        "Landscapes",
        "  jewelry ",
        "portraits",
        "underwater",
    ]
    recommendations = recommend_lenses(requests)
    for subject, lens in recommendations:
        print("{:<20} -> {}".format(subject, lens))
    print()
    print(format_report(recommendations))


