WARNING_CATEGORIES = {
    "red": [
        "engine temperature",
        "oil pressure",
        "battery charge",
        "brake system",
    ],
    "yellow": [
        "check engine",
        "tire pressure",
        "anti lock brakes",
        "traction control",
    ],
    "green": [
        "headlights",
        "cruise control",
        "turn signals",
        "eco mode",
    ],
}

SEVERITY_ORDER = {
    "red": 0,
    "yellow": 1,
    "green": 2,
    "unknown": 3,
}

ACTION_MESSAGES = {
    "red": "stop the vehicle and seek service immediately",
    "yellow": "have the system inspected soon",
    "green": "informational indicator, no action needed",
    "unknown": "unrecognised indicator, check the owner's manual",
}


def normalise(system):
    return " ".join(str(system).lower().split())


def lookup_color(system):
    target = normalise(system)
    for color, systems in WARNING_CATEGORIES.items():
        if target in systems:
            return color
    return "unknown"


def classify_warnings(systems):
    paired = [(normalise(system), lookup_color(system)) for system in systems]
    return len(paired), paired


def summarise(systems):
    count, paired = classify_warnings(systems)
    totals = {
        "red": 0,
        "yellow": 0,
        "green": 0,
        "unknown": 0,
    }
    for _, color in paired:
        totals[color] += 1
    ranked = sorted(paired, key=lambda pair: (SEVERITY_ORDER[pair[1]], pair[0]))
    return {
        "count": count,
        "pairs": paired,
        "totals": totals,
        "ranked": ranked,
    }


def format_report(systems):
    report = summarise(systems)
    lines = [
        "Indicators processed: {}".format(report["count"]),
        "Red: {red}  Yellow: {yellow}  Green: {green}  Unknown: {unknown}".format(
            **report["totals"]
        ),
    ]
    for system, color in report["ranked"]:
        lines.append("  {} [{}] -> {}".format(system, color, ACTION_MESSAGES[color]))
    return "\n".join(lines)


def main():
    dashboard = [
        "Oil Pressure",
        "cruise control",
        "check engine",
        "lane assist",
    ]
    print(classify_warnings(["oil pressure", "cruise control"]))
    print(format_report(dashboard))


if __name__ == "__main__":
    main()

