PROCESSING_LINES = {
    "paper": [
        "cardboard",
        "newspapers",
        "magazines",
        "office paper",
        "mail",
    ],
    "plastic": [
        "water bottles",
        "milk jugs",
        "detergent containers",
        "yogurt cups",
    ],
    "metal": [
        "aluminum cans",
        "steel food cans",
        "foil",
        "baking pans",
    ],
    "glass": [
        "clear bottles",
        "green bottles",
        "brown bottles",
        "glass jars",
    ],
}

UNSORTED_LINE = "landfill"

ROW = "{:<22} -> {}"


def build_item_index(lines=PROCESSING_LINES):
    """Map every accepted material to the line that processes it."""
    return {item: line for line, items in lines.items() for item in items}


def normalize(item):
    return " ".join(str(item).strip().lower().split())


def route_items(items, lines=PROCESSING_LINES):
    """Match each discarded item with its processing line."""
    index = build_item_index(lines)
    routed = []
    for item in items:
        name = normalize(item)
        routed.append((name, index.get(name, UNSORTED_LINE)))
    return routed


def summarize(routed):
    """Count how many items were sent to each line."""
    totals = {}
    for _item, line in routed:
        totals[line] = totals.get(line, 0) + 1
    return totals


def format_report(routed):
    report = [
        "Item routing report",
        "-" * 34,
    ]
    for item, line in routed:
        report.append(ROW.format(item, line))
    report.append("-" * 34)
    totals = summarize(routed)
    for line in sorted(totals):
        report.append(ROW.format(line, "{} item(s)".format(totals[line])))
    return "\n".join(report)


def main():
    discards = [
        "foil",
        "Magazines",
        "milk jugs",
        "brown bottles",
        "  office paper ",
        "garden hose",
    ]
    print(format_report(route_items(discards)))


if __name__ == "__main__":
    main()

