KNOT_CATALOG = {
    "securing lines": [
        "anchor bend",
        "bowline",
        "cleat hitch",
        "clove hitch",
    ],
    "joining ropes": [
        "figure eight bend",
        "fisherman knot",
        "sheet bend",
        "square knot",
    ],
    "stopper knots": [
        "ashley stopper",
        "figure eight",
        "monkey fist",
        "simple overhand",
    ],
}

CATEGORY_ALIASES = {
    "securing": "securing lines",
    "securing line": "securing lines",
    "joining": "joining ropes",
    "joining rope": "joining ropes",
    "stopper": "stopper knots",
    "stopper knot": "stopper knots",
}


def normalize_category(category):
    key = " ".join(str(category).strip().lower().split())
    key = CATEGORY_ALIASES.get(key, key)
    if key not in KNOT_CATALOG:
        raise KeyError("unknown knot category: {0}".format(category))
    return key


def recommend_knots(categories):
    knots = set()
    for category in categories:
        knots.update(KNOT_CATALOG[normalize_category(category)])
    flattened = sorted(knots)
    return len(flattened), flattened


def format_recommendation(categories):
    count, knots = recommend_knots(categories)
    lines = [
        "requested: {0}".format(", ".join(categories)),
        "{0} knot(s):".format(count),
    ]
    lines.extend("  - " + knot for knot in knots)
    return "\n".join(lines)


def main(argv):
    if argv:
        requests = [argv]
    else:
        requests = [[name] for name in sorted(KNOT_CATALOG)]
        requests.append(sorted(KNOT_CATALOG))
    for request in requests:
        try:
            print(format_recommendation(request))
        except KeyError as exc:
            print("rejected:", exc.args[0])
        print()


if __name__ == "__main__":
    import sys

    main(sys.argv[1:])

