BREED_GROUPS = {
    "herding": [
        "border collie",
        "german shepherd",
        "australian shepherd",
        "corgi",
        "sheepdog",
    ],
    "sporting": [
        "golden retriever",
        "labrador retriever",
        "pointer",
        "setter",
        "spaniel",
    ],
    "hound": [
        "beagle",
        "bloodhound",
        "greyhound",
        "dachshund",
        "basset hound",
    ],
}

UNKNOWN_GROUP = "unclassified"

SINGULAR_OVERRIDES = {
    "corgis": "corgi",
    "collies": "border collie",
    "setters": "setter",
    "pointers": "setter",
    "puppies": "puppy",
}


def normalize(breed):
    """Lowercase, trim and de-pluralize a user supplied breed name."""
    name = " ".join(str(breed).lower().split())
    if name in SINGULAR_OVERRIDES:
        return SINGULAR_OVERRIDES[name]
    if name.endswith("ies"):
        return name[:-3] + "y"
    if name.endswith("es") and not name.endswith("ses"):
        return name[:-2]
    if name.endswith("s"):
        return name[:-1]
    return name


def find_group(breed):
    """Return the working group whose breed list contains the given breed."""
    target = normalize(breed)
    for group, members in BREED_GROUPS.items():
        if target in members:
            return group
    return UNKNOWN_GROUP


def categorize_breeds(breeds):
    """Match every breed to its working group, preserving input order."""
    tracking = []
    for breed in breeds:
        tracking.append(
            (
                normalize(breed),
                find_group(breed),
            )
        )
    return tracking


def summarize(matches):
    """Count how many breeds landed in each working group."""
    counts = {}
    for _breed, group in matches:
        counts[group] = counts.get(group, 0) + 1
    return counts


def format_report(matches):
    lines = []
    for breed, group in matches:
        lines.append("{:<18} -> {}".format(breed, group))
    for group, count in sorted(summarize(matches).items()):
        lines.append("{:<18} :  {} breed(s)".format(group, count))
    return "\n".join(lines)


def main():
    kennel_intake = [
        "Corgis",
        "beagles",
        "Golden Retriever",
        "bloodhounds",
        "australian shepherds",
        "poodles",
    ]
    print(format_report(categorize_breeds(kennel_intake)))
    print(categorize_breeds(["corgis", "beagles"]))


if __name__ == "__main__":
    main()

