        "galaxies",
        "time travel",
    ],
    "mystery": [
        "detectives",
        "murder",
        "clues",
        "suspects",
        "investigations",
        "secrets",
    ],
}


def normalize(keyword):
    return " ".join(str(keyword).lower().split())


def find_subgenre(keyword):
    target = normalize(keyword)
    for subgenre, keywords in SUBGENRE_KEYWORDS.items():
        if target in keywords:
            return subgenre
    return None


def tag_keywords(keywords):
    return [
        (normalize(keyword), find_subgenre(keyword))
        for keyword in keywords
    ]


def group_by_subgenre(tagged):
    grouped = {}
    for keyword, subgenre in tagged:
        grouped.setdefault(subgenre, []).append(keyword)
    return grouped


def format_report(tagged):
    lines = []
    for subgenre, keywords in group_by_subgenre(tagged).items():
        label = subgenre if subgenre else "unclassified"
        lines.append("{}: {}".format(label, ", ".join(sorted(keywords))))
    return "\n".join(sorted(lines))


