    "foundation brush": [
        "liquid foundation",
        "cream contour",
        "tinted moisturizer",
        "primer",
        "liquid blush",
    ],
    "powder brush": [
        "setting powder",
        "loose bronzer",
        "mineral foundation",
        "finishing powder",
        "powder blush",
    ],
    "eyeshadow brush": [
        "lid color",
        "crease blending",
        "brow bone highlighting",
        "inner corner shimmer",
        "smudging liner",
    ],
}

BRUSH_ALIASES = {
    "foundation": "foundation brush",
    "powder": "powder brush",
    "eyeshadow": "eyeshadow brush",
    "eye shadow brush": "eyeshadow brush",
}


def normalize_brush(name):
    key = " ".join(str(name).lower().split())
    return BRUSH_ALIASES.get(key, key)


def merge_brush_usages(brushes):
    applications = set()
    unknown = []
    for brush in brushes:
        key = normalize_brush(brush)
        usages = BRUSH_USAGES.get(key)
        if usages is None:
            unknown.append(brush)
        else:
            applications.update(usages)
    if unknown:
        raise KeyError("unknown brush(es): " + ", ".join(map(str, unknown)))
    return len(applications), sorted(applications)


def format_usage_report(brushes):
    count, applications = merge_brush_usages(brushes)
    lines = [
        "Requested brushes: " + ", ".join(normalize_brush(b) for b in brushes),
        "Unique applications: {}".format(count),
    ]
    lines.extend("  - " + application for application in applications)
    return "\n".join(lines)


def main():
    requests = [
        ["powder brush"],
        ["foundation brush", "eyeshadow brush"],
        ["powder", "powder brush", "foundation"],
        list(BRUSH_USAGES),
