        "cumin",
        "coriander",
        "cardamom",
        "cinnamon",
        "cloves",
        "black pepper",
        "nutmeg"
    ],
    "herbs de provence": [
        "savory",
        "marjoram",
        "rosemary",
        "thyme",
        "oregano",
        "lavender"
    ],
    "chili powder": [
        "paprika",
        "cumin",
        "garlic powder",
        "onion powder",
        "oregano",
        "cayenne"
    ]
}


def normalize_blend_name(name):
    return " ".join(str(name).lower().replace("-", " ").split())


def gather_spices(blend_names):
    unknown = []
    spices = set()
    for raw_name in blend_names:
        name = normalize_blend_name(raw_name)
        if name in BLENDS:
            spices.update(BLENDS[name])
        else:
            unknown.append(raw_name)
    if unknown:
        raise KeyError("unknown blend(s): " + ", ".join(map(str, unknown)))
    return (
        SHELF_LIFE,
        STORAGE_CONTAINER,
        sorted(spices)
    )


def format_order(blend_names):
    shelf_life, container, spices = gather_spices(blend_names)
    lines = [
        "Blends: " + ", ".join(normalize_blend_name(n) for n in blend_names),
        "Shelf life: " + shelf_life,
        "Storage: " + container,
        "Spices ({0}):".format(len(spices))
    ]
    lines.extend("  - " + spice for spice in spices)
    return "\n".join(lines)


def main():
    orders = [
        ["chili powder"],
        ["Garam Masala", "herbs-de-provence"],
        ["chili powder", "garam masala", "chili powder"]
    ]
    for order in orders:
        print(format_order(order))
        print()
    try:
        gather_spices(["curry powder"])
    except KeyError as error:
        print("Order rejected:", error.args[0])


if __name__ == "__main__":
