)


def lookup(table, key, group):
    if key not in table:
        raise ValueError("unknown {} descriptor: {!r}".format(group, key))
    return table[key]


def parse_sample(sample):
    descriptors = sample.split(",") if isinstance(sample, str) else list(sample)
    parts = {}
    for descriptor in descriptors:
