RESOLUTIONS = {
    "standard definition": {
        "multiplier": 1,
        "bandwidth": "low",
    },
    "high definition": {
        "multiplier": 2,
        "bandwidth": "medium",
    },
    "ultra high definition": {
        "multiplier": 4,
        "bandwidth": "high",
    },
}

FRAME_RATES = {
    "cinema": 24,
    "standard": 30,
    "high": 60,
}

BITRATES = {
    "low": "blocky quality",
    "medium": "clear quality",
    "lossless": "perfect quality",
}

LEGACY_FORMATS = [
    "real video",
    "flash video",
    "quicktime movie",
]

FIELDS = (
    "resolution",
    "frame_rate",
    "bitrate",
    "container",
)


def normalize(stream):
    if isinstance(stream, dict):
        data = dict(stream)
    else:
        data = dict(zip(FIELDS, stream))
    for name, table in (("resolution", RESOLUTIONS), ("frame_rate", FRAME_RATES), ("bitrate", BITRATES),):
        if data.get(name) not in table:
            raise ValueError("unknown %s: %r" % (name, data.get(name)))
    data.setdefault("container", "modern")
    return data


def multiplier_for(stream):
    factor = RESOLUTIONS[stream["resolution"]]["multiplier"]
    if FRAME_RATES[stream["frame_rate"]] >= 60:
        factor *= 2
    if stream["container"] in LEGACY_FORMATS:
        factor = max(1, factor // 2)
    return factor


def profile(streams):
    return [(multiplier_for(s), BITRATES[s["bitrate"]]) for s in map(normalize, streams)]


def report(streams):
    lines = []
    for stream, (factor, quality) in zip(map(normalize, streams), profile(streams)):
        lines.append("x{0} {1} at {2} fps, {3} bandwidth".format(
            factor,
            quality,
            FRAME_RATES[stream["frame_rate"]],
            RESOLUTIONS[stream["resolution"]]["bandwidth"],
        ))
    return lines


def main():
    streams = [
        ("high definition", "cinema", "lossless",),
        ("ultra high definition", "high", "medium",),
        ("standard definition", "standard", "low", "flash video",),
        {
            "resolution": "ultra high definition",
            "frame_rate": "cinema",
            "bitrate": "lossless",
            "container": "quicktime movie",
        },
    ]
    print(profile(streams[:1]))
    for line in report(streams):
        print(line)


if __name__ == "__main__":
    main()

