    "commercial": {
        "power_kw": 50,
        "noise": "medium",
    },
    "industrial": {
        "power_kw": 500,
        "noise": "low",
    },
}

GENERATOR_SPECS = {
    "synchronous": {
        "efficiency": "high",
        "maintenance": "high",
    },
    "asynchronous": {
        "efficiency": "moderate",
        "maintenance": "low",
    },
}

TOWER_ADJUSTMENTS = {
    "short": -0.10,
    "medium": 0.0,
    "tall": 0.20,
}

RESTRICTED_WEATHER = [
    "hurricane",
    "tornado",
    "extreme icing",
]


def validate(conditions):
    unknown = []
    for key, table in (
        ("blade", BLADE_SPECS),
        ("generator", GENERATOR_SPECS),
        ("tower", TOWER_ADJUSTMENTS),
    ):
        value = conditions.get(key)
        if value not in table:
            unknown.append("%s=%r" % (key, value))
    if unknown:
        raise ValueError("unsupported selection: " + ", ".join(unknown))


def estimate(conditions):
    validate(conditions)
    blade = BLADE_SPECS[conditions["blade"]]
    generator = GENERATOR_SPECS[conditions["generator"]]
    adjustment = TOWER_ADJUSTMENTS[conditions["tower"]]
    weather = conditions.get("weather", "clear").lower()
    restricted = weather in RESTRICTED_WEATHER
    output_kw = 0.0 if restricted else blade["power_kw"] * (1 + adjustment)
    return {
        "output_kw": round(output_kw, 2),
        "efficiency": generator["efficiency"],
        "noise": blade["noise"],
        "maintenance": generator["maintenance"],
        "shutdown": restricted,
    }


def describe(result):
    if result["shutdown"]:
        return "shutdown: 0 kW (restricted weather)"
    return "{0:g} kW with {1} efficiency and {2} noise".format(
        result["output_kw"],
        result["efficiency"],
        result["noise"],
    )


