            "blade": "residential",
            "generator": "asynchronous",
            "tower": "short",
            "weather": "breezy",
        },
        {
            "blade": "industrial",
            "generator": "synchronous",
            "tower": "medium",
            "weather": "tornado",
        },
    ]
    for scenario in scenarios:
        label = "{blade}/{generator}/{tower}/{weather}".format(**scenario)
        print(label, "->", describe(estimate(scenario)))


