ARTICLES = ("a", "an", "the")

JUMPS = {
    "axel": {
        "base": 8,
        "risk": "high",
    },
    "lutz": {
        "base": 6,
        "risk": "medium",
    },
    "salchow": {
        "base": 4,
        "risk": "low",
    },
}

SPINS = {
    "camel spin": 3,
    "sit spin": 2,
    "upright spin": 1,
}

STEP_SEQUENCES = {
    "step sequence level one": 1,
    "step sequence level two": 3,
    "step sequence level three": 5,
}

DEDUCTIONS = [
    {"name": "fall", "penalty": 1},
    {"name": "time violation", "penalty": 1},
    {"name": "costume violation", "penalty": 1},
]

RISK_ORDER = {
    "none": 0,
    "low": 1,
    "medium": 2,
    "high": 3,
}


def normalize(element):
    words = str(element).strip().lower().split()
    if words and words[0] in ARTICLES:
        words = words[1:]
    return " ".join(words)


def classify(element):
    key = normalize(element)
    if key in JUMPS:
        return "jump", JUMPS[key]["base"], JUMPS[key]["risk"]
    if key in SPINS:
        return "spin", SPINS[key], "none"
    if key in STEP_SEQUENCES:
        return "step sequence", STEP_SEQUENCES[key], "none"
    for deduction in DEDUCTIONS:
        if deduction["name"] == key:
            return "deduction", -deduction["penalty"], "none"
    raise ValueError("unknown performance element: {!r}".format(element))


def score(routines):
    total = 0
    risk = "none"
    penalties = []
    for element in routines:
        kind, value, element_risk = classify(element)
        total += value
        if RISK_ORDER[element_risk] > RISK_ORDER[risk]:
            risk = element_risk
        if kind == "deduction":
            penalties.append(normalize(element))
    return {
        "total": total,
        "risk": risk,
        "penalties": penalties,
        "elements": [normalize(element) for element in routines],
    }


def format_report(label, result):
    lines = [
        "{}: {} points ({} risk)".format(label, result["total"], result["risk"]),
        "  elements: {}".format(", ".join(result["elements"])),
    ]
    if result["penalties"]:
        lines.append("  deductions: {}".format(", ".join(result["penalties"])))
    return "\n".join(lines)


def main():
    programs = {
        "short program": [
            "an axel",
            "a camel spin",
            "a fall",
        ],
        "free skate": [
            "a lutz",
            "a salchow",
            "a sit spin",
            "a step sequence level three",
            "a time violation",
        ],
    }
    for label, routines in programs.items():
        print(format_report(label, score(routines)))


if __name__ == "__main__":
    main()

