        return "jump", JUMPS[key]["base"], JUMPS[key]["risk"]
    if key in SPINS:
        return "spin", SPINS[key], "none"
    if key in STEP_SEQUENCES:
        return "step sequence", STEP_SEQUENCES[key], "none"
    for deduction in DEDUCTIONS:
        if deduction["name"] == key:
            return "deduction", -deduction["penalty"], "none"
    raise ValueError("unknown performance element: {!r}".format(element))


def score(routines):
    total = 0
    risk = "none"
    penalties = []
    for element in routines:
        kind, value, element_risk = classify(element)
        total += value
        if RISK_ORDER[element_risk] > RISK_ORDER[risk]:
            risk = element_risk
        if kind == "deduction":
            penalties.append(normalize(element))
    return {
        "total": total,
        "risk": risk,
        "penalties": penalties,
        "elements": [normalize(element) for element in routines]
    }


def format_report(label, result):
    lines = [
        "{}: {} points ({} risk)".format(label, result["total"], result["risk"]),
        "  elements: {}".format(", ".join(result["elements"]))
    ]
    if result["penalties"]:
        lines.append("  deductions: {}".format(", ".join(result["penalties"])))
    return "\n".join(lines)


def main():
    programs = {
        "short program": [
            "an axel",
            "a camel spin",
            "a fall"
        ],
        "free skate": [
            "a lutz",
            "a salchow",
            "a sit spin",
            "a step sequence level three",
            "a time violation"
        ]
    }
    for label, routines in programs.items():
        print(format_report(label, score(routines)))


if __name__ == "__main__":
    main()

