    1: "incisor", 2: "incisor", 3: "canine", 4: "premolar",
    5: "premolar", 6: "molar", 7: "molar", 8: "molar",
}

PRIMARY_POSITIONS = {
    1: "incisor", 2: "incisor", 3: "canine",
    4: "molar", 5: "molar",
}

ROOT_WORDS = {
    1: "one",
    2: "two",
    3: "three",
}


def _position_from_midline(offset, quadrant_index, quadrant_size):
    if quadrant_index in (0, 2):
        return quadrant_size - offset
    return offset + 1


def identify(code):
    if isinstance(code, str):
        key = code.strip().upper()
        if key not in PRIMARY_TEETH:
            raise ValueError("unknown primary tooth code: %r" % code)
        quadrant_index, offset = divmod(PRIMARY_TEETH.index(key), 5)
        position = _position_from_midline(offset, quadrant_index, 5)
        return QUADRANT_NAMES[quadrant_index], PRIMARY_POSITIONS[position]
    number = int(code)
    if number not in range(1, 33):
        raise ValueError("unknown permanent tooth number: %r" % code)
    quadrant_index, offset = divmod(number - 1, 8)
    position = _position_from_midline(offset, quadrant_index, 8)
    return QUADRANT_NAMES[quadrant_index], PERMANENT_POSITIONS[position]


def chart(teeth):
    charted = []
    for record in teeth:
        code = record["tooth"]
        condition = record["condition"].strip().lower()
        if condition not in CONDITIONS:
            raise ValueError("unknown condition: %r" % record["condition"])
        quadrant, tooth_type = identify(code)
        charted.append({
            "tooth": code,
            "quadrant": quadrant,
            "type": tooth_type,
            "roots": TOOTH_TYPES[tooth_type]["roots"],
            "edges": TOOTH_TYPES[tooth_type]["edges"],
            "condition": condition,
            "treatment": CONDITIONS[condition],
        })
    return charted


def format_report(charted):
    return [
        "tooth {tooth}: {quadrant} quadrant, {roots} roots, requires a {treatment}".format(
            tooth=item["tooth"],
            quadrant=item["quadrant"],
            roots=ROOT_WORDS[item["roots"]],
            treatment=item["treatment"],
        )
        for item in charted
    ]


def main():
    patient_records = [
        {"tooth": 3, "condition": "cavity"},
        {"tooth": 11, "condition": "fracture"},
        {"tooth": 20, "condition": "infection"},
        {"tooth": 25, "condition": "cavity"},
        {"tooth": "K", "condition": "infection"},
    ]
    for line in format_report(chart(patient_records)):
        print(line)


if __name__ == "__main__":
    main()

