def normalize(name):
    return " ".join(str(name).replace("-", " ").lower().split())


GAS_MIXES = {
    "mild steel": {
        "gas mix": "seventy five percent argon mix",
        "penetration": "deep penetration",
    },
    "stainless steel": {
        "gas mix": "ninety percent helium mix",
        "penetration": "medium penetration",
    },
    "aluminum": {
        "gas mix": "pure argon",
        "penetration": "shallow penetration",
    },
}

TRANSFER_MODES = {
    "short circuit": "low voltage",
    "globular": "medium voltage",
    "spray": "high voltage",
}

ELECTRODE_TYPES = {
    "solid wire": "minimal slag",
    "flux core": "heavy slag",
    "metal core": "light slag",
}

TOXIC_FUMES = [
    "zinc oxide",
    "ozone",
    "hexavalent chromium",
]


def lookup(table, value, label):
    key = normalize(value)
    if key not in table:
        raise ValueError(
            "unknown {}: {!r}; expected one of {}".format(
                label,
                value,
                ", ".join(sorted(table)),
            )
        )
    return table[key]


def recommend(metal, arc="short circuit", electrode="solid wire"):
    profile = lookup(GAS_MIXES, metal, "primary metal")
    return {
        "metal": normalize(metal),
        "gas mix": profile["gas mix"],
        "penetration": profile["penetration"],
        "voltage": lookup(TRANSFER_MODES, arc, "arc transfer mode"),
        "slag": lookup(ELECTRODE_TYPES, electrode, "electrode type"),
        "ventilate": list(TOXIC_FUMES),
    }


def describe(recipe):
    return "{metal}: {gas mix}, {penetration}, {voltage}, {slag}".format(**recipe)


def formulate(metals):
    jobs = [metals] if isinstance(metals, dict) else list(metals)
    return [
        recommend(
            job["metal"],
            job.get("arc", "short circuit"),
            job.get("electrode", "solid wire"),
        )
        for job in jobs
    ]


def main():
