    "single": {
        "provides": "high agility",
        "requires": "tail rotor",
    },
    "tandem": {
        "provides": "heavy lift",
        "requires": "complex gearing",
    },
    "coaxial": {
        "provides": "compact size",
        "requires": "rigid blades",
    },
}

BLADE_COUNTS = {
    2: "low drag",
    3: "moderate drag",
    4: "high stability",
}

BLADE_MATERIALS = {
    "composite": ("lightweight", "expensive"),
    "aluminum": ("standard", "affordable"),
    "wood": ("outdated", "heavy"),
}

EXTREME_MANEUVERS = [
    "autorotation",
    "loop",
    "barrel roll",
]


def validate(design):
    rotor = design["rotor"]
    blades = design["blades"]
    material = design["material"]
    if rotor not in ROTOR_CONFIGURATIONS:
        raise ValueError("unknown rotor configuration: {!r}".format(rotor))
    if blades not in BLADE_COUNTS:
        raise ValueError("unsupported blade count: {!r}".format(blades))
    if material not in BLADE_MATERIALS:
        raise ValueError("unknown blade material: {!r}".format(material))
    return rotor, blades, material


def collect_traits(design):
    rotor, blades, material = validate(design)
    config = ROTOR_CONFIGURATIONS[rotor]
    traits = [
        config["provides"],
        config["requires"],
        BLADE_COUNTS[blades],
    ]
    traits.extend(BLADE_MATERIALS[material])
    return traits


def format_traits(traits):
    return "{}, and {}".format(", ".join(traits[:-1]), traits[-1])


def extreme_maneuvers(design):
    return [m for m in design.get("maneuvers", []) if m in EXTREME_MANEUVERS]


def evaluate(rotors):
    reports = []
    for design in rotors:
        traits = collect_traits(design)
        reports.append({
            "name": design.get("name", design["rotor"]),
            "traits": traits,
            "summary": format_traits(traits),
            "extreme": extreme_maneuvers(design),
        })
    return reports


def main():
    fleet = [
        {
            "name": "Chinook",
            "rotor": "tandem",
            "blades": 4,
            "material": "composite",
            "maneuvers": ["autorotation", "hover"],
        },
        {
            "name": "Kamov",
            "rotor": "coaxial",
            "blades": 3,
            "material": "aluminum",
            "maneuvers": ["loop", "barrel roll"],
        },
        {
            "name": "Trainer",
            "rotor": "single",
            "blades": 2,
            "material": "wood",
        },
    ]
    for report in evaluate(fleet):
        print("{}: {}".format(report["name"], report["summary"]))
        if report["extreme"]:
            print("  extreme maneuvers: {}".format(", ".join(report["extreme"])))


if __name__ == "__main__":
    main()

