text_nat:
CORE_TYPES = {
    "single mode": {
        "core_microns": 9,
        "distance": "long distance",
    },
    "multi mode step": {
        "core_microns": 50,
        "distance": "short distance",
    },
    "multi mode graded": {
        "core_microns": 62,
        "distance": "medium distance",
    },
}

LIGHT_SOURCES = {
    "light emitting diode": "low speeds",
    "vertical cavity laser": "high speeds",
    "fabry perot laser": "ultra high speeds",
}

JACKET_COLORS = {
    "yellow": "single mode",
    "orange": "multi mode",
    "aqua": "laser optimized",
}

HIGH_LOSS_CONNECTORS = [
    "straight tip",
    "lucency",
    "subscriber",
]


def validate(connection):
    for field, table in (
        ("core_type", CORE_TYPES),
        ("light_source", LIGHT_SOURCES),
        ("jacket", JACKET_COLORS),
    ):
        value = connection.get(field)
        if value not in table:
            raise ValueError("unknown %s: %r" % (field, value))


def spec_for(connection):
    validate(connection)
    core = CORE_TYPES[connection["core_type"]]
    spec = {
        "core_microns": core["core_microns"],
        "distance": core["distance"],
        "speed": LIGHT_SOURCES[connection["light_source"]],
        "indication": JACKET_COLORS[connection["jacket"]],
    }
    connector = connection.get("connector")
    if connector in HIGH_LOSS_CONNECTORS:
        spec["high_loss_connector"] = connector
    return spec


def format_spec(spec):
    parts = [
        "%d micron core" % spec["core_microns"],
        spec["distance"],
        spec["speed"],
        "%s indication" % spec["indication"],
    ]
    if "high_loss_connector" in spec:
        parts.append("high loss %s connector" % spec["high_loss_connector"])
    return ", ".join(parts)


def route(connections):
    return [spec_for(connection) for connection in connections]


def main():
    layout = [
        {
            "core_type": "single mode",
            "light_source": "vertical cavity laser",
            "jacket": "yellow",
        },
        {
            "core_type": "multi mode graded",
            "light_source": "light emitting diode",
            "jacket": "orange",
            "connector": "straight tip",
        },
        {
            "core_type": "multi mode step",
            "light_source": "fabry perot laser",
            "jacket": "aqua",
        },
    ]
    for number, spec in enumerate(route(layout), start=1):
        print("link %d: %s" % (number, format_spec(spec)))


if __name__ == "__main__":
    main()

