text_nat:
WING_SHAPES = {
    "delta": {
        "speed": "high",
        "glide": "low",
    },
    "straight": {
        "speed": "low",
        "glide": "high",
    },
    "swept": {
        "speed": "moderate",
        "glide": "moderate",
    },
}

NOSE_FOLDS = {
    "pointed": {
        "drag": "reduced",
        "damage_risk": "increased",
        "balance": "neutral",
    },
    "blunt": {
        "drag": "increased",
        "damage_risk": "reduced",
        "balance": "neutral",
    },
    "heavy": {
        "drag": "increased",
        "damage_risk": "reduced",
        "balance": "shifted forward",
    },
}

TAIL_MODS = {
    "winglets": {
        "effect": "improved stability",
        "points": 2,
    },
    "elevators": {
        "effect": "pitch control",
        "points": 1,
    },
    "rudders": {
        "effect": "yaw control",
        "points": 1,
    },
}

ADVANCED_TECHNIQUES = [
    "water bomb base",
    "squash fold",
    "petal fold",
]

LEVEL_POINTS = {
    "low": 1,
    "moderate": 2,
    "high": 3,
}


def _lookup(table, key, kind):
    if key not in table:
        raise ValueError("unknown {}: {!r}".format(kind, key))
    return table[key]


def characteristics(design):
    wing = _lookup(WING_SHAPES, design["wing"], "wing shape")
    nose = _lookup(NOSE_FOLDS, design["nose"], "nose fold")
    traits = [
        "{} speed".format(wing["speed"]),
        "{} glide".format(wing["glide"]),
        "{} drag".format(nose["drag"]),
        "{} damage risk".format(nose["damage_risk"]),
    ]
    if nose["balance"] != "neutral":
        traits.append("center of gravity {}".format(nose["balance"]))
    for name in design.get("tail", []):
        traits.append(_lookup(TAIL_MODS, name, "tail modification")["effect"])
    return traits


def score(design):
    wing = _lookup(WING_SHAPES, design["wing"], "wing shape")
    total = LEVEL_POINTS[wing["speed"]] + LEVEL_POINTS[wing["glide"]]
    if _lookup(NOSE_FOLDS, design["nose"], "nose fold")["drag"] == "reduced":
        total += 2
    for name in design.get("tail", []):
        total += TAIL_MODS[name]["points"]
    for technique in design.get("techniques", []):
        if technique in ADVANCED_TECHNIQUES:
            total += 1
    return total


def _sentence(items):
    if len(items) == 1:
        return items[0]
    return ", ".join(items[:-1]) + ", and " + items[-1]


def grade(designs):
    return [
        {
            "name": design["name"],
            "traits": characteristics(design),
            "summary": _sentence(characteristics(design)),
            "score": score(design),
        }
        for design in designs
    ]


def main():
    designs = [
        {
            "name": "Glider",
            "wing": "straight",
            "nose": "blunt",
            "tail": ["winglets"],
        },
        {
            "name": "Dart",
            "wing": "delta",
            "nose": "pointed",
            "tail": ["elevators", "rudders"],
            "techniques": ["squash fold"],
        },
        {
            "name": "Cruiser",
            "wing": "swept",
            "nose": "heavy",
            "tail": ["winglets", "elevators"],
            "techniques": ["water bomb base", "petal fold"],
        },
    ]
    for report in grade(designs):
        print("{} ({} pts): {}".format(report["name"], report["score"], report["summary"]))


if __name__ == "__main__":
    main()

