text_nat:
HULL_CLASSES = {
    "attack": {
        "priorities": ["speed", "torpedo capacity"],
        "summary": "prioritizes speed and torpedo capacity",
    },
    "ballistic": {
        "priorities": ["stealth", "missile capacity"],
        "summary": "prioritizes stealth and missile capacity",
    },
    "research": {
        "priorities": ["visibility", "manipulator arms"],
        "summary": "prioritizes visibility and manipulator arms",
    },
}

DEPTH_ZONES = {
    "periscope": {
        "effect": "allows communication",
        "safe": True,
    },
    "shallow": {
        "effect": "avoids commercial shipping",
        "safe": True,
    },
    "test": {
        "effect": "stresses the hull",
        "safe": False,
    },
    "crush": {
        "effect": "causes structural failure",
        "safe": False,
    },
}

PROPULSION_TYPES = {
    "nuclear": "offers unlimited endurance",
    "diesel electric": "requires snorkeling",
    "air independent": "offers quiet operation",
}

EMERGENCY_ASCENT = [
    "main ballast blow",
    "emergency propulsion",
    "drop weights",
]


def describe(profile):
    hull = HULL_CLASSES[profile["hull"]]
    zone = DEPTH_ZONES[profile["depth"]]
    propulsion = PROPULSION_TYPES[profile["propulsion"]]
    return {
        "hull": profile["hull"],
        "clauses": [
            hull["summary"],
            zone["effect"],
            propulsion,
        ],
        "emergency": [] if zone["safe"] else list(EMERGENCY_ASCENT),
    }


def format_summary(record):
    clauses = record["clauses"]
    sentence = ", ".join(clauses[:-1]) + ", and " + clauses[-1]
    line = record["hull"].capitalize() + " submarine " + sentence
    if record["emergency"]:
        line += "; emergency ascent: " + ", ".join(record["emergency"])
    return line


def plan(profiles):
    return [format_summary(describe(profile)) for profile in profiles]


def main():
    fleet = [
        {
            "hull": "attack",
            "depth": "periscope",
            "propulsion": "nuclear",
        },
        {
            "hull": "ballistic",
            "depth": "test",
            "propulsion": "air independent",
        },
        {
            "hull": "research",
            "depth": "shallow",
            "propulsion": "diesel electric",
        },
    ]
    for line in plan(fleet):
        print(line)


if __name__ == "__main__":
    main()

