    "lugged": "traditional",
    "welded": "strong",
    "monocoque": "seamless",
}

AGGRESSIVE_POSTURES = [
    "aerodynamic tuck",
    "sprinting drops",
    "climbing hoods",
]


def describe(frame):
    traits = list(MATERIAL_TRAITS.get(frame["material"], []))
    for key, table in (
        ("shape", SHAPE_TRAITS),
        ("joining", JOINING_TRAITS),
    ):
        trait = table.get(frame.get(key))
        if trait:
            traits.append(trait)
    return traits


def join_phrase(traits):
    if len(traits) == 1:
        return traits[0]
    return ", ".join(traits[:-1]) + ", and " + traits[-1]


def analyze(frames):
    summaries = []
    for frame in frames:
        traits = describe(frame)
        summaries.append({
            "name": frame.get("name", frame["material"]),
            "summary": join_phrase(traits),
            "aggressive": frame.get("posture") in AGGRESSIVE_POSTURES,
        })
    return summaries


