FRAMES = {
    "micro": {
        "payload_kg": 0.05,
        "trait": "flies indoors",
    },
    "standard": {
        "payload_kg": 1.0,
        "trait": "shoots video",
    },
    "heavy lift": {
        "payload_kg": 10.0,
        "trait": "maps terrain",
    },
}

MOTOR_KV = {
    "high": "spins fast and lifts light loads",
    "medium": "balances speed and torque",
    "low": "spins slowly and swings large propellers",
}

BATTERIES = {
    "four cell": 14,
    "six cell": 22,
    "eight cell": 29,
}

HAZARDS = [
    "high winds",
    "magnetic interference",
    "freezing rain",
]


def describe(frame, kv, battery):
    return [
        "carries {0:g} kilogram".format(FRAMES[frame]["payload_kg"]),
        MOTOR_KV[kv],
        "provides {0} volts".format(BATTERIES[battery]),
    ]


def validate(mission):
    problems = []
    if mission.get("frame") not in FRAMES:
        problems.append("unknown frame {0!r}".format(mission.get("frame")))
    if mission.get("kv") not in MOTOR_KV:
        problems.append("unknown kv rating {0!r}".format(mission.get("kv")))
    if mission.get("battery") not in BATTERIES:
        problems.append("unknown battery {0!r}".format(mission.get("battery")))
    for hazard in mission.get("hazards", []):
        if hazard not in HAZARDS:
            problems.append("unknown hazard {0!r}".format(hazard))
    return problems


def capability(mission):
    frame, kv = mission["frame"], mission["kv"]
    battery = mission["battery"]
    hazards = [h for h in mission.get("hazards", []) if h in HAZARDS]
    return {
        "name": mission["name"],
        "summary": ", and ".join([", ".join(describe(frame, kv, battery)[:2]), describe(frame, kv, battery)[2]]),
        "payload_kg": FRAMES[frame]["payload_kg"],
        "voltage": BATTERIES[battery],
        "role": FRAMES[frame]["trait"],
        "hazards": hazards,
        "grounded": len(hazards) > 1,
    }


def estimate(missions):
    reports = []
    for mission in missions:
        problems = validate(mission)
        if problems:
            reports.append({
                "name": mission.get("name", "unnamed"),
                "errors": problems,
            })
        else:
            reports.append(capability(mission))
    return reports


def render(report):
    if "errors" in report:
        return "{0}: rejected ({1})".format(report["name"], "; ".join(report["errors"]))
    lines = [
        "{0}: {1}".format(report["name"], report["summary"]),
        "  role: {0}".format(report["role"]),
    ]
    if report["hazards"]:
        lines.append("  hazards: {0}".format(", ".join(report["hazards"])))
    if report["grounded"]:
        lines.append("  verdict: grounded until conditions improve")
    return "\n".join(lines)


def main():
    missions = [
        {
            "name": "survey run",
            "frame": "standard",
            "kv": "medium",
            "battery": "six cell",
        },
        {
            "name": "warehouse inspection",
            "frame": "micro",
            "kv": "high",
            "battery": "four cell",
            "hazards": ["magnetic interference"],
        },
        {
            "name": "ridge mapping",
            "frame": "heavy lift",
            "kv": "low",
            "battery": "eight cell",
            "hazards": ["high winds", "freezing rain"],
        },
        {
            "name": "prototype hop",
            "frame": "nano",
            "kv": "medium",
            "battery": "two cell",
        },
    ]
    for report in estimate(missions):
        print(render(report))


if __name__ == "__main__":
    main()

