    "crevasse rescue",
]


def normalise(route):
    return {
        "name": str(route.get("name", "unnamed route")).strip(),
        "category": str(route.get("category", "")).strip().lower(),
        "treatment": str(route.get("treatment", "")).strip().lower(),
        "elongation": str(route.get("elongation", "")).strip().lower(),
        "hazards": [str(h).strip().lower() for h in route.get("hazards", [])],
    }


def validate(route):
    problems = []
    for field, table in (
        ("category", ROPE_CATEGORIES),
        ("treatment", CORE_TREATMENTS),
        ("elongation", ELONGATION_TYPES),
    ):
        if route[field] not in table:
            problems.append("unknown {}: {!r}".format(field, route[field]))
    return problems


def recommend(route):
    hazards = [h for h in route["hazards"] if h in HIGH_RISK_SCENARIOS]
    return {
