FUEL_TYPES = {
    "seasoned wood": {
        "trait": "produces high creosote",
        "signature": "tall flames",
        "clean_burning": False,
    },
    "natural gas": {
        "trait": "burns clean",
        "signature": "water vapor",
        "clean_burning": True,
    },
    "wood pellets": {
        "trait": "offers controlled burns",
        "signature": "minimal ash",
        "clean_burning": False,
    },
}

DRAFT_SYSTEMS = {
    "natural draft": "relies on heat rising",
    "direct vent": "pulls outside air",
    "induced draft": "uses an electric fan",
}

LINER_MATERIALS = {
    "clay tiles": {
        "trait": "traditional but cracks over time",
        "gas_only": False,
        "corrosion_proof": False,
    },
    "aluminum": {
        "trait": "only for gas appliances",
        "gas_only": True,
        "corrosion_proof": False,
    },
    "stainless steel": {
        "trait": "resists all corrosive byproducts",
        "gas_only": False,
        "corrosion_proof": True,
    },
}

CHIMNEY_HAZARDS = [
    "bird nests",
    "heavy soot buildup",
    "downdrafts",
]


def join_clauses(parts):
    if len(parts) < 2:
        return "".join(parts)
    return ", ".join(parts[:-1]) + ", and " + parts[-1]


def validate(hearth):
    for field, table in (("fuel", FUEL_TYPES), ("draft", DRAFT_SYSTEMS), ("liner", LINER_MATERIALS)):
        value = hearth.get(field)
        if value not in table:
            raise ValueError("unknown {}: {!r}".format(field, value))
    for hazard in hearth.get("hazards", []):
        if hazard not in CHIMNEY_HAZARDS:
            raise ValueError("unknown chimney hazard: {!r}".format(hazard))


def venting_warnings(fuel, draft, liner, hazards):
    warnings = []
    if LINER_MATERIALS[liner]["gas_only"] and fuel != "natural gas":
        warnings.append("{} liner cannot vent {}".format(liner, fuel))
    if not FUEL_TYPES[fuel]["clean_burning"] and not LINER_MATERIALS[liner]["corrosion_proof"]:
        warnings.append("{} leaves deposits the {} liner will not survive".format(fuel, liner))
    if draft == "induced draft":
        warnings.append("electric fan needs backup power to keep venting")
    for hazard in hazards:
        warnings.append("clear {} before the next burn".format(hazard))
    return warnings


def size(hearths):
    reports = []
    for hearth in hearths:
        validate(hearth)
        fuel, draft, liner = hearth["fuel"], hearth["draft"], hearth["liner"]
        hazards = list(hearth.get("hazards", []))
        warnings = venting_warnings(fuel, draft, liner, hazards)
        reports.append({
            "name": hearth.get("name", "{} hearth".format(fuel)),
            "configuration": join_clauses([
                FUEL_TYPES[fuel]["trait"],
                DRAFT_SYSTEMS[draft],
                LINER_MATERIALS[liner]["trait"],
            ]),
            "byproduct": FUEL_TYPES[fuel]["signature"],
            "warnings": warnings,
            "safe": not warnings,
        })
    return reports


def main():
    installations = [
        {
            "name": "parlor insert",
            "fuel": "natural gas",
            "draft": "direct vent",
            "liner": "aluminum",
        },
        {
            "name": "cabin firebox",
            "fuel": "seasoned wood",
            "draft": "natural draft",
            "liner": "clay tiles",
            "hazards": ["bird nests", "heavy soot buildup"],
        },
        {
            "name": "basement stove",
            "fuel": "wood pellets",
            "draft": "induced draft",
            "liner": "stainless steel",
            "hazards": ["downdrafts"],
        },
    ]
    for report in size(installations):
        print("{}: {}.".format(report["name"], report["configuration"]))
        print("  byproduct: {}".format(report["byproduct"]))
        if report["safe"]:
            print("  safe to vent as built")
        for warning in report["warnings"]:
            print("  warning: {}".format(warning))


if __name__ == "__main__":
    main()

