        "oil_type": "conventional",
        "oil_volume": 5.0,
        "coolant_volume": 11.0,
    },
}

CLASS_ALIASES = {
    "compact": "compact car",
    "sedan": "midsize sedan",
    "truck": "heavy duty truck",
    "suv": "luxury suv",
    "ev": "electric vehicle",
    "electric": "electric vehicle",
    "hybrid car": "hybrid",
}

OIL_ALIASES = {
    "none": "",
    "no oil": "",
    "n/a": "",
    "battery coolant only": "",
    "synthetic oil": "synthetic",
    "full synthetic oil": "full synthetic",
    "low viscosity oil": "low viscosity",
    "conventional oil": "conventional",
}


def normalize(text):
    if text is None:
        return ""
    return " ".join(str(text).lower().replace("-", " ").split())


def resolve_class(name):
    key = normalize(name)
    return CLASS_ALIASES.get(key, key)


def resolve_oil(name):
    key = normalize(name)
    return OIL_ALIASES.get(key, key)


def volume_matches(expected, actual):
    try:
        return abs(float(actual) - expected) < 1e-9
    except (TypeError, ValueError):
        return False


def check_record(record):
    vehicle_class, oil_type, oil_volume, coolant_volume = record
    key = resolve_class(vehicle_class)
    spec = SPEC.get(key)
    if spec is None:
        return (key, "noncompliant")
    checks = [
        resolve_oil(oil_type) == spec["oil_type"],
        volume_matches(spec["oil_volume"], oil_volume),
        volume_matches(spec["coolant_volume"], coolant_volume),
    ]
    return (key, "compliant" if all(checks) else "noncompliant")


def evaluate(vehicles):
    return [check_record(record) for record in vehicles]


def format_report(results):
    lines = [
        "{:<20}{}".format("VEHICLE CLASS", "STATUS"),
        "-" * 34,
    ]
    for vehicle_class, status in results:
        lines.append("{:<20}{}".format(vehicle_class, status))
    return "\n".join(lines)


def main():
    records = [
        ("compact car", "synthetic", 4, 7),
        ("midsize sedan", "synthetic blend", 5, 9),
        ("heavy duty truck", "conventional oil", 12, 20),
        ("sports car", "full synthetic", 6, 9),
        ("luxury suv", "synthetic", 8, 14),
        ("hybrid", "low viscosity", 3, 5),
        ("EV", "none", 0, 10),
        ("minivan", "synthetic", 5, 11),
    ]
    print(format_report(evaluate(records)))


if __name__ == "__main__":
    main()

