def conflicts(modality, conditions):
    profile = CONTRAST_AGENTS[normalize(modality)]
    blocked = set(profile["contraindications"])
    return sorted(blocked.intersection(normalize(c) for c in conditions))


def screen(patients):
    return [not conflicts(modality, conditions) for modality, conditions in patients]


def report(patients):
    lines = []
    for (modality, conditions), cleared in zip(patients, screen(patients)):
        agent = CONTRAST_AGENTS[normalize(modality)]["agent"]
        found = conflicts(modality, conditions)
        status = "CLEAR" if cleared else "HOLD: " + ", ".join(found)
        lines.append("{} ({}) -> {}".format(modality, agent, status))
    return lines


def main():
    patients = [
        ("magnetic resonance imaging", ["kidney failure"]),
        ("computed tomography", ["hypertension"]),
        ("positron emission tomography", ["high blood sugar", "asthma"]),
        ("ultrasound", []),
        ("fluoroscopy", ["Bowel Obstruction"]),
        ("angiography", ["bleeding risk", "thyroid issues"]),
        ("arthrography", ["osteoarthritis"]),
        ("myelography", ["seizure history"])
    ]
    print(screen(patients))
    for line in report(patients):
        print(line)


if __name__ == "__main__":
    main()

