    "reverse": {
        "stress": "compressional",
        "movement": "vertical upward",
    },
    "strike slip": {
        "stress": "shear",
        "movement": "horizontal",
    },
    "oblique": {
        "stress": "mixed",
        "movement": "diagonal",
    },
    "thrust": {
        "stress": "compressional",
        "movement": "shallow upward",
    },
    "listric": {
        "stress": "extensional",
        "movement": "curved downward",
    },
    "detachment": {
        "stress": "extensional",
        "movement": "nearly horizontal",
    },
    "transform": {
        "stress": "shear",
        "movement": "plate boundary horizontal",
    },
}


def normalize(text):
    return " ".join(str(text).lower().replace("-", " ").split())


def signature(observation):
    stress, movement = observation
    return (
        normalize(stress),
        normalize(movement),
    )


