    (data["stress"], data["movement"]): name
    for name, data in FAULT_REFERENCE.items()
}


def classify(faults):
    return [LOOKUP.get(signature(fault), "unknown") for fault in faults]


def stress_families():
    families = {}
    for name, data in FAULT_REFERENCE.items():
        families.setdefault(data["stress"], []).append(name)
    return families


def report(faults):
    lines = []
    for observation, name in zip(faults, classify(faults)):
        stress, movement = signature(observation)
        lines.append(
            "{0:>13} + {1:<26} -> {2}".format(stress, movement, name),
