ENGINE_SPECS = {
    "turboprop": {
        "max_altitude": 30000,
        "speed": "low speed",
    },
    "turbofan": {
        "max_altitude": 45000,
        "speed": "high subsonic speed",
    },
    "turbojet": {
        "max_altitude": 60000,
        "speed": "supersonic speed",
    },
    "ramjet": {
        "max_altitude": 80000,
        "speed": "hypersonic speed",
    },
    "scramjet": {
        "max_altitude": 100000,
        "speed": "high hypersonic speed",
    },
    "pulsejet": {
        "max_altitude": 20000,
        "speed": "low subsonic speed",
    },
    "piston": {
        "max_altitude": 15000,
        "speed": "low speed",
    },
    "electric": {
        "max_altitude": 10000,
        "speed": "ultra low speed",
    },
}


def spec_for(engine):
    key = str(engine).strip().lower()
    if key not in ENGINE_SPECS:
        raise ValueError("unknown engine type: {0!r}; known types: {1}".format(
            engine,
            ", ".join(sorted(ENGINE_SPECS)),
        ))
    return ENGINE_SPECS[key]


def analyze(engines):
    results = []
    for engine, altitude in engines:
        spec = spec_for(engine)
        if altitude < spec["max_altitude"]:
            results.append("optimal")
        else:
            results.append("sub-optimal")
    return results


def describe(engine, altitude, verdict):
    spec = spec_for(engine)
    return "{0:<10} {1:>7} ft / max {2:>6} ft ({3:<22}) -> {4}".format(
        str(engine).strip().lower(),
        altitude,
        spec["max_altitude"],
        spec["speed"],
        verdict,
    )


def summarize(results):
    return {
        "total": len(results),
        "optimal": results.count("optimal"),
        "sub-optimal": results.count("sub-optimal"),
    }


def main():
    flights = [
        ("turboprop", 40000),
        ("turbofan", 38000),
        ("turbojet", 60000),
        ("ramjet", 75000),
        ("scramjet", 99000),
        ("pulsejet", 21000),
        ("piston", 9000),
        ("electric", 10000),
    ]
