    for (engine, altitude), verdict in zip(flights, verdicts):
        print(describe(engine, altitude, verdict))
    totals = summarize(verdicts)
    print("\n{total} flights analyzed: {optimal} optimal, "
          "{sub-optimal} sub-optimal".format(**totals))


if __name__ == "__main__":
    main()

