DIRTY = "dirty read"
NON_REPEATABLE = "non repeatable read"
PHANTOM = "phantom read"
WRITE_SKEW = "write skew"

ALL_PHENOMENA = frozenset({
    DIRTY,
    NON_REPEATABLE,
    PHANTOM,
    WRITE_SKEW,
})

PREVENTED = {
    "read uncommitted": frozenset(),
    "read committed": frozenset({
        DIRTY,
    }),
    "repeatable read": frozenset({
        DIRTY,
        NON_REPEATABLE,
    }),
    "serializable": frozenset({
        DIRTY,
        NON_REPEATABLE,
        PHANTOM,
    }),
    "snapshot isolation": frozenset({
        DIRTY,
        NON_REPEATABLE,
        PHANTOM,
    }),
    "read write": frozenset(),
    "read only": ALL_PHENOMENA,
    "strict serializable": ALL_PHENOMENA,
}

REAL_TIME_ORDERING = frozenset({
    "strict serializable",
})


def _canonical(text):
    cleaned = str(text).strip().lower().replace("-", " ").replace("_", " ")
    return " ".join(cleaned.split())


def prevented_phenomena(level):
    key = _canonical(level)
    if key not in PREVENTED:
        raise ValueError("unknown isolation level: {!r}".format(level))
    return PREVENTED[key]


def validate(transactions):
    results = []
    for level, phenomenon in transactions:
        observed = _canonical(phenomenon)
        if observed not in ALL_PHENOMENA:
            raise ValueError("unknown read phenomenon: {!r}".format(phenomenon))
        results.append(observed in prevented_phenomena(level))
    return results


def summarize(transactions, results):
    return {
        "checked": len(results),
        "violations": sum(1 for flag in results if flag),
        "compliant": sum(1 for flag in results if not flag),
        "levels": sorted({_canonical(level) for level, _phenomenon in transactions}),
    }


def format_report(transactions, results):
    lines = [
        "isolation level              phenomenon             violation",
    ]
    for (level, phenomenon), flag in zip(transactions, results):
        key = _canonical(level)
        label = key + (" *" if key in REAL_TIME_ORDERING else "")
        lines.append("{:<28} {:<22} {}".format(label, _canonical(phenomenon), flag))
    stats = summarize(transactions, results)
    lines.append("{checked} checked, {violations} violations, {compliant} allowed".format(**stats))
    lines.append("levels seen: " + ", ".join(stats["levels"]))
    return "\n".join(lines)


def main():
    transactions = [
        ("read uncommitted", "dirty read"),
        ("read committed", "dirty read"),
        ("read committed", "phantom read"),
        ("repeatable read", "non repeatable read"),
        ("repeatable read", "phantom read"),
        ("serializable", "phantom read"),
        ("snapshot isolation", "write skew"),
        ("read write", "non repeatable read"),
        ("read only", "dirty read"),
        ("strict serializable", "write skew"),
    ]
    print(format_report(transactions, validate(transactions)))


if __name__ == "__main__":
    main()

