HASH_PARAMETERS = {
    "md5": {
        "block_size": 512,
        "digest_size": 128,
    },
    "sha1": {
        "block_size": 512,
        "digest_size": 160,
    },
    "sha256": {
        "block_size": 512,
        "digest_size": 256,
    },
    "sha512": {
        "block_size": 1024,
        "digest_size": 512,
    },
    "sha3_256": {
        "block_size": 1088,
        "digest_size": 256,
    },
    "sha3_512": {
        "block_size": 576,
        "digest_size": 512,
    },
    "blake2b": {
        "block_size": 1024,
        "digest_size": 512,
    },
    "ripemd160": {
        "block_size": 512,
        "digest_size": 160,
    },
}

ALIASES = {
    "message digest five": "md5",
    "secure hash one": "sha1",
    "sha-1": "sha1",
    "secure hash two fifty six": "sha256",
    "sha-256": "sha256",
    "secure hash five twelve": "sha512",
    "sha-512": "sha512",
    "secure hash three two fifty six": "sha3_256",
    "sha3-256": "sha3_256",
    "secure hash three five twelve": "sha3_512",
    "sha3-512": "sha3_512",
    "blake two b": "blake2b",
    "ripemd one sixty": "ripemd160",
    "ripemd-160": "ripemd160",
}

WEAK_ALGORITHMS = frozenset([
    "md5",
    "sha1",
    "ripemd160",
])


def normalize(name):
    key = " ".join(str(name).split()).lower()
    return ALIASES.get(key, key.replace(" ", "_"))


def verify(algorithms):
    results = []
    for name in algorithms:
        key = normalize(name)
        if key not in HASH_PARAMETERS:
            raise KeyError("unknown hash algorithm: {!r}".format(name))
        params = HASH_PARAMETERS[key]
        results.append((
            params["block_size"],
            params["digest_size"],
        ))
    return results


def audit_report(algorithms):
    lines = []
    for name, (block, digest) in zip(algorithms, verify(algorithms)):
        status = "WEAK" if normalize(name) in WEAK_ALGORITHMS else "OK"
        lines.append("{:<32} block={:>5} digest={:>4}  {}".format(name, block, digest, status))
    return "\n".join(lines)


def main():
    requested = [
        "message digest five",
        "secure hash one",
        "secure hash two fifty six",
        "secure hash five twelve",
        "secure hash three two fifty six",
        "secure hash three five twelve",
        "blake two b",
        "ripemd one sixty",
    ]
    print(audit_report(requested))
    print()
    print("md5 parameters:", verify(["message digest five"]))


if __name__ == "__main__":
    main()

