def normalize(name):
    """Reduce a spot color name to its registry key form."""
    return " ".join(str(name).strip().lower().split())


def lookup(name):
    """Return the CMYK mixture registered for a single spot color."""
    key = normalize(name)
    if key not in CMYK_REGISTRY:
        raise KeyError("unknown spot color: {!r}".format(name))
    return CMYK_REGISTRY[key]


def convert(colors):
    """Translate spot color names into CMYK percentage tuples."""
    return [lookup(color) for color in colors]


def describe(name):
