import re
from collections import Counter

LEVEL_ALIASES = {
    "vlow": "very low",
    "v low": "very low",
    "lo": "low",
    "med": "medium",
    "mid": "medium",
    "hi": "high",
}

LEVEL_ORDER = [
    "very low",
    "low",
    "medium",
    "high",
]

FACIES_TABLE = {
    ("low", "low"): "greenschist facies",
    ("medium", "medium"): "amphibolite facies",
    ("medium", "high"): "granulite facies",
    ("high", "low"): "blueschist facies",
    ("high", "high"): "eclogite facies",
    ("very low", "very low"): "zeolite facies",
    ("low", "very low"): "prehnite pumpellyite facies",
    ("low", "high"): "hornfels facies",
}


def normalize_level(value):
    if not isinstance(value, str):
        raise TypeError("levels must be given as strings, got %r" % (value,))
    text = re.sub(r"[\s_-]+", " ", value.strip().lower())
    text = LEVEL_ALIASES.get(text, text)
    if text not in LEVEL_ORDER:
        raise ValueError("unknown level %r, expected one of %s" % (value, ", ".join(LEVEL_ORDER)))
    return text


def facies_for(pressure, temperature):
    key = (normalize_level(pressure), normalize_level(temperature))
    if key not in FACIES_TABLE:
        raise ValueError("no facies defined for pressure %s and temperature %s" % key)
    return FACIES_TABLE[key]


def grade(samples):
    graded = []
    for sample in samples:
        pressure, temperature = sample
        graded.append(facies_for(pressure, temperature))
    return graded


def summarize(facies_names):
    counts = Counter(facies_names)
    return {name: counts[name] for name in sorted(counts)}


def sort_key(sample):
    pressure, temperature = sample
    return (
        LEVEL_ORDER.index(normalize_level(pressure)),
        LEVEL_ORDER.index(normalize_level(temperature)),
    )


def format_report(samples, facies_names):
    lines = [
        "Metamorphic facies report",
        "=" * 25,
    ]
    for sample, name in sorted(zip(samples, facies_names), key=lambda pair: sort_key(pair[0])):
        pressure, temperature = (normalize_level(level) for level in sample)
        lines.append("%9s P / %9s T -> %s" % (pressure, temperature, name))
    lines.append("")
    for name, count in summarize(facies_names).items():
        lines.append("%2d x %s" % (count, name))
    return "\n".join(lines)


def main():
    samples = [
        ("low", "low"),
        ("med", "med"),
        ("medium", "high"),
        ("high", "low"),
        ("high", "high"),
        ("very low", "very-low"),
        ("low", "v low"),
        ("low", "hi"),
    ]
    print(format_report(samples, grade(samples)))


if __name__ == "__main__":
    main()

