    ],
}

BROWSER_ENGINE = {
    browser: engine
    for engine, browsers in ENGINE_BROWSERS.items()
    for browser in browsers
}

UNKNOWN_ENGINE = "unknown"


def normalize(client):
    """Reduce a raw browser name to the canonical lookup key."""
    return " ".join(str(client).strip().lower().split())


def engine_of(client):
    """Return the rendering engine driving a single browser name."""
    return BROWSER_ENGINE.get(normalize(client), UNKNOWN_ENGINE)


def render(clients):
    """Map every browser name in clients to its rendering engine."""
    return [engine_of(client) for client in clients]


def group_by_engine(clients):
    """Bucket the given browser names under the engine that renders them."""
    groups = {}
    for client, engine in zip(clients, render(clients)):
        groups.setdefault(engine, []).append(normalize(client))
    return groups


def report(clients):
    """Build a human readable routing summary, one line per engine."""
    groups = group_by_engine(clients)
    lines = []
    for engine in sorted(groups):
        lines.append("{}: {}".format(engine, ", ".join(groups[engine])))
    return "\n".join(lines)


