    ("wide rock foundation", "massive concrete weight"): "gravity dam",
    ("narrow canyon", "structural curvature"): "arch dam",
    ("wide valley", "spaced triangular supports"): "buttress dam",
    ("broad floodplain", "compacted soil"): "earthfill dam",
    ("seismic zone", "loose rock with core"): "rockfill dam",
    ("flat river bed", "adjustable gates"): "barrage dam",
    ("dry valley", "flood control gates"): "detention dam",
    ("steep mountain stream", "minimal reservoir"): "diversion dam"
}


def _normalize(text):
    return " ".join(str(text).strip().lower().split())


def _validate(entry):
    if not isinstance(entry, (tuple, list)) or len(entry) != 2:
        raise ValueError(
            "each structure must be a (valley, mechanism) pair, got {!r}".format(
                entry
            )
        )
    valley, mechanism = entry
    return _normalize(valley), _normalize(mechanism)


def assess(structures):
    suitable = []
    for entry in structures:
        profile = _validate(entry)
        suitable.append(DAM_RULES.get(profile, UNSUITABLE))
    return suitable


def format_report(structures, dams):
    lines = [
        "Valley profile assessment",
        "=" * 58
    ]
    for entry, dam in zip(structures, dams):
        valley, mechanism = _validate(entry)
        lines.append("{:<22} {:<28} -> {}".format(valley, mechanism, dam))
    return lines


def summarize(dams):
    counts = {}
    for dam in dams:
        counts[dam] = counts.get(dam, 0) + 1
    return sorted(
        counts.items(),
        key=lambda item: (-item[1], item[0])
    )


def main():
    sites = [
        ("Narrow Canyon", "structural curvature"),
        ("wide rock foundation", "massive concrete weight"),
        ("broad floodplain", "compacted soil"),
        ("seismic zone", "loose rock with core"),
        ("flat river bed", "adjustable gates"),
        ("dry valley", "flood control gates"),
        ("steep mountain stream", "minimal reservoir"),
        ("wide valley", "spaced triangular supports"),
        ("narrow canyon", "compacted soil")
    ]
    dams = assess(sites)
    for line in format_report(sites, dams):
        print(line)
    print()
    for dam, count in summarize(dams):
        print("{:>2}x {}".format(count, dam))
    print(
        "\n{} sites assessed, {} distinct recommendations".format(
            len(sites),
            len(summarize(dams))
        )
    )


if __name__ == "__main__":
    main()

