PLUG_REGISTRY = {
    "a": (
        "two flat parallel pins",
        120,
    ),
    "b": (
        "two flat parallel pins with ground",
        120,
    ),
    "c": (
        "two round pins",
        230,
    ),
    "e": (
        "two round pins with earth pin",
        230,
    ),
    "f": (
        "two round pins with earth clips",
        230,
    ),
    "g": (
        "three rectangular pins",
        230,
    ),
    "h": (
        "three round pins in a triangle",
        230,
    ),
    "i": (
        "two flat inverted v pins",
        230,
    ),
}


def normalize(plug_type):
    key = str(plug_type).strip().lower()
    if key not in PLUG_REGISTRY:
        raise KeyError("unknown plug type: {!r}".format(plug_type))
    return key


def adapt(travelers):
    return [PLUG_REGISTRY[normalize(plug)] for plug in travelers]


def needs_converter(home_plug, travelers):
    home_voltage = PLUG_REGISTRY[normalize(home_plug)][1]
    return [
        normalize(plug)
        for plug, (_, voltage) in zip(travelers, adapt(travelers))
        if voltage != home_voltage
    ]


def format_report(home_plug, travelers):
    home = normalize(home_plug)
    converters = set(needs_converter(home, travelers))
    lines = [
        "home plug: type {} ({} V)".format(home, PLUG_REGISTRY[home][1]),
    ]
    for plug, (pins, voltage) in zip(travelers, adapt(travelers)):
        note = "converter" if normalize(plug) in converters else "adapter only"
        lines.append(
            "type {}: {} at {} V -> {}".format(normalize(plug), pins, voltage, note),
        )
    return "\n".join(lines)


def main():
    itinerary = [
        "a",
        "C",
        "g",
        " i ",
        "h",
    ]
    print(format_report("b", itinerary))
    print(adapt(["c", "e", "f"]))


