from fractions import Fraction

QUARK_CHARGES = {
    "up": Fraction(2, 3),
    "down": Fraction(-1, 3),
    "strange": Fraction(-1, 3),
    "anti up": Fraction(-2, 3),
    "anti down": Fraction(1, 3),
    "anti strange": Fraction(1, 3),
}

HADRON_QUARKS = {
    "proton": ["up", "up", "down"],
    "neutron": ["up", "down", "down"],
    "positive pion": ["up", "anti down"],
    "negative pion": ["anti up", "down"],
    "positive kaon": ["up", "anti strange"],
    "negative kaon": ["anti up", "strange"],
    "lambda baryon": [
        "up",
        "down",
        "strange",
    ],
    "omega baryon": ["strange", "strange", "strange"],
}


def quark_charge(quark):
    try:
        return QUARK_CHARGES[quark]
    except KeyError:
        raise ValueError("unknown quark: {0}".format(quark))


def hadron_charge(hadron):
    try:
        quarks = HADRON_QUARKS[hadron]
    except KeyError:
        raise ValueError("unknown hadron: {0}".format(hadron))
    total = sum(
        (quark_charge(quark) for quark in quarks),
        Fraction(0),
    )
    return round(total)


def construct(hadrons):
    return [hadron_charge(hadron) for hadron in hadrons]


def format_report(hadrons):
    charges = construct(hadrons)
    lines = []
    for hadron, charge in zip(hadrons, charges):
        content = " + ".join(HADRON_QUARKS[hadron])
        lines.append(
            "{0:<14} {1:<34} {2:+d}".format(hadron, content, charge),
        )
    return "\n".join(lines)


def main():
    sample = [
        "proton",
        "neutron",
        "positive pion",
        "negative kaon",
        "lambda baryon",
        "omega baryon",
    ]
    print(format_report(sample))
    print("charges:", construct(sample))
    totals = {
        "neutral hadrons": sum(1 for c in construct(sample) if c == 0),
        "charged hadrons": sum(1 for c in construct(sample) if c != 0),
    }
    for label, count in totals.items():
        print("{0}: {1}".format(label, count))


if __name__ == "__main__":
    main()

