MATERIALS = {
    "concrete": (2400, "low", "excellent"),
    "steel": (7850, "high", "poor"),
    "timber": (600, "medium", "poor"),
    "brick": (1900, "medium", "excellent"),
    "glass": (2500, "high", "poor"),
    "aluminum": (2700, "high", "poor"),
    "fiberglass": (1500, "medium", "medium"),
    "plaster": (800, "low", "excellent"),
}

UNKNOWN = (
    0,
    "unknown",
    "unknown",
)


def normalize(material):
    """Reduce a user-supplied material name to a lookup key."""
    if not isinstance(material, str):
        return ""
    return material.strip().lower()


def evaluate(material):
    """Return (density, cost category, fire rating) for a material."""
    return MATERIALS.get(normalize(material), UNKNOWN)


def density_of(material):
    return evaluate(material)[0]


def is_known(material):
    return normalize(material) in MATERIALS


def mass_of(material, volume):
    """Mass in kilograms of a given volume (cubic meters) of material."""
    if volume < 0:
        raise ValueError("volume must be non-negative")
    return density_of(material) * volume


def fire_safe_materials(ratings=frozenset(["excellent"])):
    accepted = set(ratings)
    return sorted(
        name
        for name, (_, _, rating) in MATERIALS.items()
        if rating in accepted
    )


def group_by_cost():
    groups = {
        "low": [],
        "medium": [],
        "high": [],
    }
    for name, (_, cost, _) in sorted(MATERIALS.items()):
        groups[cost].append(name)
    return groups


def format_row(material):
    density, cost, rating = evaluate(material)
    return "{:<12}{:>8}{:>10}{:>12}".format(material, density, cost, rating)


def report(materials):
    lines = [
        "{:<12}{:>8}{:>10}{:>12}".format("material", "kg/m3", "cost", "fire"),
        "-" * 42,
    ]
    for material in materials:
        lines.append(format_row(material))
    return "\n".join(lines)


def main():
    requested = [
        "concrete",
        "Steel",
        "timber",
        "fiberglass",
        "carbon nanotube",
    ]
    print(report(requested))
    print()
    resistant = fire_safe_materials([
        "excellent",
        "medium",
    ])
    print("fire safe:", ", ".join(resistant))
    for cost, names in group_by_cost().items():
        print("{} cost: {}".format(cost, ", ".join(names)))
    print()
    beam = {
        "material": "timber",
        "volume": 0.36,
    }
    print("beam mass: {:.1f} kg".format(mass_of(beam["material"], beam["volume"])))
    for name in requested:
        if not is_known(name):
            print("unrecognised material: {}".format(name))


if __name__ == "__main__":
    main()

