text_nat:
MENU = {
    "margarita": ("tequila", "lime juice", "salt rim"),
    "martini": ("gin", "vermouth", "olive"),
    "mojito": ("rum", "mint", "lime wedge"),
    "old fashioned": ("bourbon", "bitters", "orange peel"),
    "moscow mule": ("vodka", "ginger beer", "lime wedge"),
    "negroni": ("gin", "campari", "orange peel"),
    "daiquiri": ("rum", "lime juice", "lime wheel"),
    "manhattan": ("rye", "vermouth", "cherry"),
}

ALIASES = {
    "old-fashioned": "old fashioned",
    "oldfashioned": "old fashioned",
    "moscow-mule": "moscow mule",
    "mule": "moscow mule",
    "gin martini": "martini",
    "classic martini": "martini",
}

SUFFIXES = (
    " cocktail",
    " on the rocks",
    " up",
)


def normalize(name):
    """Reduce a free-form drink name to a menu key."""
    if not isinstance(name, str):
        return ""
    cleaned = " ".join(name.strip().lower().split())
    for suffix in SUFFIXES:
        if cleaned.endswith(suffix):
            cleaned = cleaned[: -len(suffix)].strip()
    return ALIASES.get(cleaned, cleaned)


def mix(order):
    """Return (spirit, mixer, garnish) for a cocktail order."""
    return MENU.get(normalize(order), (None, None, None))


def recipe_card(order):
    """Describe an order as a printable dictionary of fields."""
    spirit, mixer, garnish = mix(order)
    if spirit is None:
        return {
            "drink": str(order),
            "known": False,
            "steps": [],
        }
    return {
        "drink": normalize(order),
        "known": True,
        "steps": [
            "Pour 2 oz {}.".format(spirit),
            "Add {}.".format(mixer),
            "Finish with {}.".format(garnish),
        ],
    }


def shopping_list(orders):
    """Count every ingredient needed for a round of drinks."""
    tally = {}
    for order in orders:
        for ingredient in mix(order):
            if ingredient is not None:
                tally[ingredient] = tally.get(ingredient, 0) + 1
    return tally


def main():
    round_of_drinks = [
        "Margarita",
        "old-fashioned",
        "classic martini",
        "mojito cocktail",
        "Shirley Temple",
    ]
    for order in round_of_drinks:
        card = recipe_card(order)
        print("{} -> {}".format(card["drink"], mix(order)))
        for step in card["steps"]:
            print("   ", step)
    print("Shopping list:")
    for ingredient, count in sorted(shopping_list(round_of_drinks).items()):
        print("   {} x{}".format(ingredient, count))


if __name__ == "__main__":
    main()

