    ),
    "injera": (
        "Ethiopia",
        "teff",
        100,
    ),
}

UNKNOWN_SPEC = (
    "unknown",
    "unknown",
    0,
)


def bake(bread):
    """Return (country, primary flour, hydration percentage) for a bread."""
    if not isinstance(bread, str):
        return UNKNOWN_SPEC
    return BREAD_SPECS.get(bread.strip().lower(), UNKNOWN_SPEC)


def hydration_class(hydration):
    """Describe a hydration percentage in baker's terms."""
    thresholds = [
        (0, "not a dough"),
        (65, "stiff"),
        (75, "standard"),
        (90, "wet"),
        (101, "batter"),
    ]
    for limit, label in thresholds:
        if hydration < limit:
            return label
    return "unknown"


def describe(bread):
    """Build a one-line human readable description of a bread."""
    country, flour, hydration = bake(bread)
    return "{}: {} bread made from {} at {}% hydration ({})".format(
        bread,
        country,
        flour,
        hydration,
        hydration_class(hydration),
    )


def flours_by_country():
    """Map each country of origin to the sorted flours it is known for."""
    grouped = {}
    for bread in BREAD_SPECS:
        country, flour, _hydration = bake(bread)
        grouped.setdefault(country, set()).add(flour)
    return {country: sorted(flours) for country, flours in grouped.items()}


def report(breads):
    """Render descriptions for many breads, one per line."""
    return "\n".join(describe(bread) for bread in breads)


def main():
    requested = [
