text_nat:
INPUT_PAIRS = [
    (0, 0),
    (0, 1),
    (1, 0),
    (1, 1),
]

GATE_FUNCTIONS = {
    "and": lambda a, b: a & b,
    "or": lambda a, b: a | b,
    "nand": lambda a, b: 1 - (a & b),
    "nor": lambda a, b: 1 - (a | b),
    "xor": lambda a, b: a ^ b,
    "xnor": lambda a, b: 1 - (a ^ b),
    "imply": lambda a, b: (1 - a) | b,
    "nimply": lambda a, b: a & (1 - b),
}

UNKNOWN_OUTPUT = tuple(0 for _ in INPUT_PAIRS)


def normalize(gate):
    return str(gate).strip().lower()


def simulate(gate):
    func = GATE_FUNCTIONS.get(normalize(gate))
    if func is None:
        return UNKNOWN_OUTPUT
    return tuple(func(a, b) for a, b in INPUT_PAIRS)


def describe(gate):
    name = normalize(gate)
    outputs = simulate(name)
    return {
        "gate": name,
        "known": name in GATE_FUNCTIONS,
        "outputs": outputs,
        "high_count": sum(outputs),
    }


def format_table(gate):
    outputs = simulate(gate)
    lines = [
        "{} truth table".format(normalize(gate)),
        "a b | out",
        "----+----",
    ]
    for (a, b), out in zip(INPUT_PAIRS, outputs):
        lines.append("{} {} |  {}".format(a, b, out))
    return "\n".join(lines)


def equivalent_gates(outputs):
    wanted = tuple(outputs)
    return sorted(name for name in GATE_FUNCTIONS if simulate(name) == wanted)


def main():
    gates = [
        "and",
        "or",
        "nand",
        "nor",
        "xor",
        "xnor",
        "imply",
        "nimply",
        "maybe",
    ]
    for gate in gates:
        print(format_table(gate))
        info = describe(gate)
        print("known={known} high_count={high_count}".format(**info))
        print()
    for probe in [
        (0, 1, 1, 0),
        (1, 1, 0, 1),
        (1, 1, 1, 1),
    ]:
        print(probe, "->", equivalent_gates(probe) or ["none"])


if __name__ == "__main__":
    main()

