HONEY_VARIETIES = {
    "clover": ("light", "mild", "fast"),
    "manuka": ("dark", "earthy", "slow"),
    "orange blossom": ("light", "citrus", "medium"),
    "tupelo": ("light", "buttery", "very slow"),
    "buckwheat": ("very dark", "robust", "slow"),
    "acacia": ("very light", "sweet", "very slow"),
    "sage": ("light", "mild", "slow"),
    "lavender": ("medium", "floral", "medium"),
}

UNKNOWN = (
    "unknown",
    "unknown",
    "unknown",
)

CRYSTALLIZATION_ORDER = [
    "very slow",
    "slow",
    "medium",
    "fast",
    "unknown",
]

SLOW_SPEEDS = frozenset([
    "very slow",
    "slow",
])


def normalize(variety):
    """Reduce a user-supplied variety name to a dictionary key."""
    if not isinstance(variety, str):
        return ""
    return " ".join(variety.lower().replace("-", " ").replace("_", " ").split())


def honey(variety):
    """Return (color grade, flavor profile, crystallization speed) for a variety."""
    return HONEY_VARIETIES.get(normalize(variety), UNKNOWN)


def describe(variety):
    """Render a one-line human readable description of a honey variety."""
    color, flavor, speed = honey(variety)
    if color == "unknown":
        return "{}: not a catalogued variety".format(variety)
    return "{}: {} in color, {} flavor, crystallizes {}".format(
        variety, color, flavor, speed,
    )


def group_by_speed(varieties):
    """Map each crystallization speed to the sorted varieties that share it."""
    groups = {speed: [] for speed in CRYSTALLIZATION_ORDER}
    for variety in varieties:
        groups[honey(variety)[2]].append(variety)
    return {speed: sorted(names) for speed, names in groups.items() if names}


def slow_crystallizers(varieties):
    """Varieties whose honey resists crystallization, slowest first."""
    ranked = sorted(
        varieties,
        key=lambda name: CRYSTALLIZATION_ORDER.index(honey(name)[2]),
    )
    return [name for name in ranked if honey(name)[2] in SLOW_SPEEDS]


def main():
    catalogue = sorted(HONEY_VARIETIES) + [
        "Orange-Blossom",
        "fireweed",
    ]
    for variety in catalogue:
        print(describe(variety))
    print()
    for speed, names in group_by_speed(catalogue).items():
        print("{:>10}: {}".format(speed, ", ".join(names)))
    print()
    print("keeps longest:", ", ".join(slow_crystallizers(catalogue)))
    print("tupelo ->", honey("tupelo"))


if __name__ == "__main__":
    main()

