SWORD_SPECS = {
    "gladius": (60, "single hand", "thrusting"),
    "spatha": (80, "single hand", "slashing"),
    "falchion": (70, "single hand", "chopping"),
    "rapier": (100, "complex guard", "thrusting"),
    "broadsword": (80, "basket hilt", "slashing"),
    "longsword": (100, "two hand", "mixed"),
    "claymore": (130, "crossguard", "slashing"),
    "cutlass": (70, "cup hilt", "slashing"),
}

UNKNOWN_SPEC = (
    0,
    "unknown",
    "unknown",
)


def sword(type):
    """Return (blade length in cm, hilt style, primary usage) for a sword name."""
    if not isinstance(type, str):
        return UNKNOWN_SPEC
    return SWORD_SPECS.get(type.strip().lower(), UNKNOWN_SPEC)


def describe(type):
    """Render a one-line human readable description of a sword."""
    length, hilt, usage = sword(type)
    if length == 0:
        return "{0}: unknown weapon".format(type)
    return "{0}: {1} cm blade, {2} hilt, used for {3}".format(
        type,
        length,
        hilt,
        usage,
    )


def group_by_usage(names):
    """Map each primary usage to the sorted names of swords sharing it."""
    groups = {}
    for name in names:
        _, _, usage = sword(name)
        groups.setdefault(usage, []).append(name)
    return {usage: sorted(members) for usage, members in groups.items()}


def longest_blade(names):
    """Return the name and length of the longest blade among the given swords."""
    ranked = sorted(
        names,
        key=lambda name: (-sword(name)[0], name),
    )
    best = ranked[0]
    return best, sword(best)[0]


def main():
    catalogue = [
        "rapier",
        "gladius",
        "claymore",
        "cutlass",
        "longsword",
        "katana",
    ]
    for name in catalogue:
        print(describe(name))
