}

LONGEVITY_RANK = {
    "unknown": 0,
    "low": 1,
    "medium": 2,
    "high": 3,
    "very high": 4,
}


def normalize(material):
    key = " ".join(str(material).lower().replace("_", " ").split())
    return ALIASES.get(key, key)


def ribbon(material):
    return RIBBON_SPECS.get(normalize(material), UNKNOWN_SPEC)


def describe(material):
