CLASS_STATS = {
    "warrior": {"health": 100, "mana": 20},
    "mage": {"health": 40, "mana": 100},
    "rogue": {"health": 60, "mana": 40},
    "cleric": {"health": 80, "mana": 80},
}

RACE_BONUS = {
    "human": {"health": 10, "mana": 10},
    "elf": {"health": 0, "mana": 20},
    "orc": {"health": 20, "mana": 0},
    "dwarf": {"health": 15, "mana": 5},
}

ITEM_BONUS = {
    "sword": {"health": 5, "mana": 0},
    "staff": {"health": 0, "mana": 10},
    "shield": {"health": 15, "mana": 0},
    "cloak": {"health": 5, "mana": 5},
}


def validate(class_name, race_name, items):
    if class_name not in CLASS_STATS:
        raise ValueError("unknown class: %s" % class_name)
    if race_name not in RACE_BONUS:
        raise ValueError("unknown race: %s" % race_name)
    unknown = [name for name in items if name not in ITEM_BONUS]
    if unknown:
        raise ValueError("unknown items: %s" % ", ".join(unknown))


def evaluate(character):
    class_name, race_name, items = character
    class_name = class_name.lower()
    race_name = race_name.lower()
    items = [name.lower() for name in items]
    validate(class_name, race_name, items)
    base = CLASS_STATS[class_name]
    race = RACE_BONUS[race_name]
    health = base["health"] + race["health"]
    mana = base["mana"] + race["mana"]
    for name in items:
        health += ITEM_BONUS[name]["health"]
        mana += ITEM_BONUS[name]["mana"]
    return (
        health,
        mana,
    )


def format_report(character):
    class_name, race_name, items = character
    health, mana = evaluate(character)
    gear = ", ".join(items) if items else "nothing"
    parts = [
        "%s %s" % (race_name.title(), class_name.title()),
        "equipped with %s" % gear,
        "-> health %d, mana %d" % (health, mana),
    ]
    return " ".join(parts)


def main():
    roster = [
        ("warrior", "elf", ["sword", "shield"]),
        ("mage", "human", ["staff", "cloak"]),
        ("rogue", "orc", ["sword"]),
        ("cleric", "dwarf", []),
    ]
    for character in roster:
        print(format_report(character))
    try:
        evaluate(("bard", "human", ["lute"]))
    except ValueError as error:
        print("rejected: %s" % error)


if __name__ == "__main__":
    main()

