        "small": 3.00,
        "medium": 4.00,
        "large": 5.00
    },
    "cappuccino": {
        "small": 3.00,
        "medium": 4.00,
        "large": 4.50
    },
    "mocha": {
        "small": 4.00,
        "medium": 5.00,
        "large": 6.00
    }
}

MILK_SURCHARGES = {
    "whole": 0.00,
    "skim": 0.00,
    "soy": 0.50,
    "oat": 0.75,
    "almond": 0.50
}


def price_of(beverage, size, milk):
    name = beverage.strip().lower()
    cup = size.strip().lower()
    dairy = milk.strip().lower()
    if name not in MENU:
        raise ValueError("unknown beverage: {}".format(beverage))
    if cup not in MENU[name]:
        raise ValueError("unknown size: {}".format(size))
    if dairy not in MILK_SURCHARGES:
        raise ValueError("unknown milk: {}".format(milk))
    return MENU[name][cup] + MILK_SURCHARGES[dairy]


def calculate(order):
    return float(sum(price_of(*item) for item in order))


def itemize(order):
    return [
        (
            "{} {} with {} milk".format(size, beverage, milk),
            price_of(beverage, size, milk)
        )
        for beverage, size, milk in order
    ]


def format_receipt(order):
    lines = ["{:<34}{:>7.2f}".format(label, cost) for label, cost in itemize(order)]
    lines.append("-" * 41)
    lines.append("{:<34}{:>7.2f}".format("TOTAL", calculate(order)))
    return "\n".join(lines)


def main():
    orders = [
        [
            ("latte", "large", "oat")
        ],
        [
            ("espresso", "small", "whole"),
            ("mocha", "medium", "almond"),
            ("cappuccino", "large", "soy")
        ]
    ]
    for index, order in enumerate(orders, start=1):
        print("Order #{}".format(index))
        print(format_receipt(order))
        print()


if __name__ == "__main__":
    main()

