CONTAINER_SPECS = {
    "food": {
        "weight": 2,
        "volume": 3,
    },
    "machinery": {
        "weight": 5,
        "volume": 2,
    },
    "medicine": {
        "weight": 1,
        "volume": 1,
    },
    "weapon": {
        "weight": 4,
        "volume": 4,
    },
}

SHIP_LIMITS = {
    "weight": 50,
    "volume": 60,
}


def validate(manifest):
    """Return a normalised manifest, raising on unknown types or bad counts."""
    cleaned = []
    for kind, quantity in manifest:
        name = kind.strip().lower()
        if name not in CONTAINER_SPECS:
            raise ValueError("unknown container type: {0}".format(kind))
        if quantity < 0:
            raise ValueError("negative quantity for {0}".format(name))
        cleaned.append((name, int(quantity),))
    return cleaned


def load(manifest):
    """Determine whether the manifest fits aboard the ship."""
    totals = {
        "weight": 0,
        "volume": 0,
    }
    for name, quantity in validate(manifest):
        spec = CONTAINER_SPECS[name]
        totals["weight"] += spec["weight"] * quantity
        totals["volume"] += spec["volume"] * quantity
    fits = (
        totals["weight"] <= SHIP_LIMITS["weight"]
        and totals["volume"] <= SHIP_LIMITS["volume"]
    )
    return (fits, totals["weight"], totals["volume"],)


def report(manifest):
    """Render a human readable summary of a load attempt."""
    fits, weight, volume = load(manifest)
    lines = [
        "Manifest: " + ", ".join(
            "{0} x{1}".format(kind, quantity) for kind, quantity in manifest
        ),
        "Weight: {0}/{1} tons".format(weight, SHIP_LIMITS["weight"]),
        "Volume: {0}/{1} cubic meters".format(volume, SHIP_LIMITS["volume"]),
        "Verdict: " + ("cleared for launch" if fits else "overloaded"),
    ]
    return "\n".join(lines)


def main():
    manifests = [
        [("food", 10,)],
        [
            ("machinery", 6),
            ("medicine", 12),
        ],
        [
            ("food", 5),
            ("weapon", 9),
            ("medicine", 3),
        ],
    ]
    for entry in manifests:
        print(report(entry))
        print()


if __name__ == "__main__":
    main()

