RECIPES = {
    "healing": (
        "water",
        "herbs",
        "mushroom",
    ),
    "mana": (
        "water",
        "crystal",
        "glowing root",
    ),
    "strength": (
        "alcohol",
        "bone",
        "fiery leaf",
    ),
    "invisibility": (
        "oil",
        "ghost feather",
        "moonstone",
    ),
}

BREW_ORDER = [
    "healing",
    "mana",
    "strength",
    "invisibility",
]


def normalize(ingredients):
    return {str(item).strip().lower() for item in ingredients}


def brew(ingredients):
    available = normalize(ingredients)
    for potion in BREW_ORDER:
        if all(item in available for item in RECIPES[potion]):
            return potion
    return "sludge"


def missing_items(ingredients, potion):
    available = normalize(ingredients)
    return [item for item in RECIPES[potion] if item not in available]


def describe(ingredients):
    potion = brew(ingredients)
    if potion != "sludge":
        return "{} -> {}".format(", ".join(ingredients), potion)
    gaps = [
        "{} (needs {})".format(name, ", ".join(missing_items(ingredients, name)))
        for name in BREW_ORDER
    ]
    return "{} -> sludge; closest attempts: {}".format(
        ", ".join(ingredients) or "nothing",
        "; ".join(gaps),
    )


def main():
    batches = [
        ["water", "herbs", "mushroom", "bone"],
        ["Water", "Crystal", "Glowing Root"],
        ["alcohol", "bone", "fiery leaf", "water", "herbs"],
        ["oil", "ghost feather", "moonstone"],
        ["oil", "bone", "mushroom"],
        [],
    ]
    for batch in batches:
        print(describe(batch))


if __name__ == "__main__":
    main()

