text_nat:
SKILLS = {
    "backflip": {
        "difficulty": 3.2,
        "category": "acrobatic",
    },
    "cartwheel": {
        "difficulty": 1.1,
        "category": "acrobatic",
    },
    "pirouette": {
        "difficulty": 2.5,
        "category": "dance",
    },
    "handstand": {
        "difficulty": 1.8,
        "category": "strength",
    },
}

REQUIRED_CATEGORIES = frozenset({
    "acrobatic",
    "dance",
    "strength",
})

ALL_CATEGORY_BONUS = 0.5


def skill_score(name, deduction):
    if name not in SKILLS:
        raise ValueError("unknown skill: {!r}".format(name))
    if deduction < 0:
        raise ValueError("deduction for {} must not be negative".format(name))
    return max(0.0, SKILLS[name]["difficulty"] - deduction)


def categories_performed(routine):
    return {SKILLS[name]["category"] for name, _ in routine}


def bonus_earned(routine):
    return REQUIRED_CATEGORIES.issubset(categories_performed(routine))


def score(routine):
    total = sum(skill_score(name, deduction) for name, deduction in routine)
    if bonus_earned(routine):
        total += ALL_CATEGORY_BONUS
    return round(total, 2)


def format_report(routine):
    lines = [
        "{:<11}{:>6}{:>7}{:>7}".format("skill", "diff", "ded", "score"),
    ]
    for name, deduction in routine:
        lines.append("{:<11}{:>6.1f}{:>7.1f}{:>7.2f}".format(
            name,
            SKILLS[name]["difficulty"],
            deduction,
            skill_score(name, deduction),
        ))
    lines.extend([
        "bonus: {:.1f}".format(ALL_CATEGORY_BONUS if bonus_earned(routine) else 0.0),
        "total: {:.2f}".format(score(routine)),
    ])
    return "\n".join(lines)


def main():
    routines = {
        "single element": [
            ("backflip", 0.0),
        ],
        "sloppy acro pass": [
            ("backflip", 3.5),
            ("cartwheel", 0.4),
        ],
        "full routine": [
            ("backflip", 0.3),
            ("pirouette", 0.2),
            ("handstand", 0.5),
        ],
    }
    for label, routine in routines.items():
        print(label)
        print(format_report(routine))
        print()


if __name__ == "__main__":
    main()

