import math

RIDES = (
    "roller coaster",
    "water ride",
    "drop tower",
    "haunted house",
)

RIDE_DATA = {
    "roller coaster": {
        "capacity": 24,
        "cycle_minutes": 3,
    },
    "water ride": {
        "capacity": 16,
        "cycle_minutes": 5,
    },
    "drop tower": {
        "capacity": 12,
        "cycle_minutes": 2,
    },
    "haunted house": {
        "capacity": 8,
        "cycle_minutes": 4,
    },
}


def validate(visitors):
    if len(visitors) != len(RIDES):
        raise ValueError("expected %d visitor counts" % len(RIDES))
    for name, count in zip(RIDES, visitors):
        if not isinstance(count, int) or isinstance(count, bool):
            raise TypeError("visitor count for %s must be an int" % name)
        if count < 0:
            raise ValueError("visitor count for %s must not be negative" % name)


def wait_for(ride, count):
    data = RIDE_DATA[ride]
    cycles = math.ceil(count / data["capacity"])
    return cycles * data["cycle_minutes"]


def estimate(visitors):
    validate(visitors)
    return tuple(wait_for(ride, count) for ride, count in zip(RIDES, visitors))


def format_report(visitors):
    waits = estimate(visitors)
    lines = [
        "Ride                 Visitors   Wait",
    ]
    for ride, count, wait in zip(RIDES, visitors, waits):
        lines.append("%-20s %8d %4d min" % (ride, count, wait))
    lines.append("%-20s %8d %4d min" % ("TOTAL", sum(visitors), max(waits)))
    return "\n".join(lines)


