PASTRIES = {
    "croissant": {
        "prep": 45,
        "bake": 20,
    },
    "muffin": {
        "prep": 15,
        "bake": 25,
    },
    "tart": {
        "prep": 30,
        "bake": 35,
    },
    "cookie": {
        "prep": 10,
        "bake": 12,
    },
}


def _lookup(name):
    key = str(name).strip().lower()
    if key not in PASTRIES:
        raise ValueError("unknown pastry: {!r}".format(name))
    return key


def timeline(orders):
    """Return a per-item schedule for one prep station and one oven."""
    prep_free = 0
    oven_free = 0
    steps = []
    for name in orders:
        key = _lookup(name)
