    "wood": 1,
    "brick": 2,
    "wheat": 3,
    "ore": 4,
}

BONUSES = (
    {
        "label": "full set",
        "points": 5,
        "requires": {"wood": 1, "brick": 1, "wheat": 1, "ore": 1},
    },
    {
        "label": "ore baron",
        "points": 3,
        "requires": {"ore": 3},
    },
    {
        "label": "lumber camp",
        "points": 2,
        "requires": {"wood": 4},
    },
)


def count_resources(resources):
    counts = {name: 0 for name in RESOURCE_POINTS}
    for raw in resources:
        key = str(raw).strip().lower()
        if key not in counts:
            known = ", ".join(sorted(RESOURCE_POINTS))
            raise ValueError("unknown resource %r (expected one of: %s)" % (raw, known))
        counts[key] += 1
    return counts


def base_score(counts):
