SEAT_PRICES = {
    "standard": 15.0,
    "recliner": 20.0,
    "imax": 25.0,
    "box": 30.0
}

AGE_MULTIPLIERS = {
    "child": 0.50,
    "senior": 0.75,
    "adult": 1.00
}

SHOWTIME_MODIFIERS = {
    "morning": -5.0,
    "afternoon": -2.0,
    "evening": 0.0,
    "midnight": 3.0
}

MINIMUM_PRICE = 5.0


def normalize(request):
    seat, age, showtime = request
    parts = (
        seat.strip().lower(),
        age.strip().lower(),
        showtime.strip().lower()
    )
    tables = (
        (parts[0], SEAT_PRICES, "seat type"),
        (parts[1], AGE_MULTIPLIERS, "age category"),
        (parts[2], SHOWTIME_MODIFIERS, "showtime")
    )
    for key, table, label in tables:
        if key not in table:
            raise ValueError("unknown %s: %r" % (label, key))
    return parts


def price_of(request):
    seat, age, showtime = normalize(request)
    base = SEAT_PRICES[seat] * AGE_MULTIPLIERS[age]
    return max(base + SHOWTIME_MODIFIERS[showtime], MINIMUM_PRICE)


def ticketing(requests):
    return [price_of(request) for request in requests]


def format_receipt(requests, prices):
    lines = [
        "{:<10} {:<7} {:<10} {:>8}".format("SEAT", "AGE", "SHOWTIME", "PRICE")
    ]
    for (seat, age, showtime), price in zip(requests, prices):
        lines.append(
            "{:<10} {:<7} {:<10} {:>8}".format(
                seat.lower(),
                age.lower(),
                showtime.lower(),
                "${:.2f}".format(price)
            )
        )
    lines.append("{:<29} {:>8}".format("TOTAL", "${:.2f}".format(sum(prices))))
    return "\n".join(lines)


def main():
    orders = [
        ("standard", "adult", "morning"),
        ("recliner", "child", "afternoon"),
        ("imax", "senior", "evening"),
        ("box", "adult", "midnight"),
        ("standard", "child", "morning")
    ]
    prices = ticketing(orders)
    print(format_receipt(orders, prices))


if __name__ == "__main__":
    main()

