text_nat:
PATTERN_ALIASES = {
    "straight": "straight",
    "sleek": "straight",
    "wavy": "wavy",
    "loose waves": "wavy",
    "curly": "curly",
    "spiral": "curly",
    "coily": "coily",
    "tightly coiled": "coily",
    "kinky": "coily",
}

POROSITY_ALIASES = {
    "low": "low",
    "resistant": "low",
    "medium": "medium",
    "normal": "medium",
    "high": "high",
    "highly porous": "high",
    "damaged": "high",
}

CURL_ROUTINES = {
    "straight": {
        "low": ("shaft", ["clarifying shampoo", "lightweight mousse", "serum", "heat protectant"],),
        "medium": ("shaft", ["volumizing foam", "milk", "serum", "shine spray"],),
        "high": ("shaft", ["protein filler", "bond builder", "milk", "sealing serum"],),
    },
    "wavy": {
        "low": ("wave", ["gel", "lightweight mousse", "curl refresher", "clarifying shampoo"],),
        "medium": ("wave", ["cream", "gel", "leave-in", "curl refresher"],),
        "high": ("wave", ["leave-in", "cream", "oil", "bond builder"],),
    },
    "curly": {
        "low": ("curl", ["gel", "humectant spray", "leave-in", "clarifying shampoo"],),
        "medium": ("curl", ["cream", "gel", "leave-in", "oil"],),
        "high": ("curl", ["cream", "butter", "oil", "bond builder"],),
    },
    "coily": {
        "low": ("coil", ["humectant spray", "leave-in", "gel", "steam treatment"],),
        "medium": ("coil", ["cream", "butter", "leave-in", "oil"],),
        "high": ("coil", ["butter", "cream", "oil", "bond builder"],),
    },
}

INGREDIENT_PROPERTIES = {
    "shea butter": {"retention": 0.92, "delivery": "butter"},
    "mango butter": {"retention": 0.85, "delivery": "butter"},
    "coconut oil": {"retention": 0.71, "delivery": "oil"},
    "argan oil": {"retention": 0.66, "delivery": "oil"},
    "glycerin": {"retention": 0.80, "delivery": "humectant spray"},
    "honey": {"retention": 0.74, "delivery": "humectant spray"},
    "aloe vera": {"retention": 0.58, "delivery": "leave-in"},
    "hydrolyzed protein": {"retention": 0.49, "delivery": "bond builder"},
}


def _normalize(value, aliases, label):
    key = str(value).strip().lower()
    if key not in aliases:
        raise ValueError("unrecognized {0}: {1}".format(label, value))
    return aliases[key]


def _top_product(products, ingredients):
    boosts = {}
    for name in ingredients:
        props = INGREDIENT_PROPERTIES.get(str(name).strip().lower())
        if props:
            channel = props["delivery"]
            boosts[channel] = boosts.get(channel, 0.0) + props["retention"]
    ranked = sorted(
        enumerate(products),
        key=lambda pair: (-boosts.get(pair[1], 0.0), pair[0]),
    )
    return ranked[0][1]


def recommend(strand):
    pattern = _normalize(strand["texture"], PATTERN_ALIASES, "texture")
