        "cross-cell",
        "double-cell",
        "vented-panel",
        "spar-frame",
    ],
}

LINE_TENSIONS = {
    (0, 8): "slack (20 daN dacron)",
    (8, 14): "light (30 daN dacron)",
    (14, 22): "medium (50 daN dyneema)",
    (22, 34): "firm (80 daN dyneema)",
    (34, 48): "heavy (120 daN dyneema)",
    (48, 90): "extreme (200 daN spectra)",
}

SURFACE_BY_LINES = {
    1: "single",
    2: "dual",
    4: "quad",
}

REQUIRED_FIELDS = (
    "speed_kph",
    "gust_kph",
    "lines",
    "maneuverability",
)


def tension_for(speed_kph):
    for (low, high), tension in LINE_TENSIONS.items():
        if low <= speed_kph < high:
            return tension
    raise ValueError("wind speed %r outside rated envelope" % speed_kph)


def classify(wind):
    missing = [field for field in REQUIRED_FIELDS if field not in wind]
    if missing:
        raise KeyError("missing weather statistics: " + ", ".join(missing))
    speed = wind["speed_kph"]
    tension = tension_for(speed)
    lines = wind["lines"]
    if speed >= 34 or wind["gust_kph"] - speed >= 20:
        architecture = "box"
    elif lines >= 4 or wind["maneuverability"] == "traction":
        architecture = "parafoil"
    else:
        architecture = "delta"
    surfaces = KITE_ARCHITECTURES[architecture]
    surface = SURFACE_BY_LINES.get(lines, "")
    if surface not in surfaces:
        surface = surfaces[-1] if tension.startswith("extreme") else surfaces[0]
    return (architecture, surface)


def format_report(station, wind):
    architecture, surface = classify(wind)
    return "%-12s %-9s %-13s %s" % (
        station,
        architecture,
        surface,
        tension_for(wind["speed_kph"]),
    )


def main():
