        ("Morecambe", {
            "speed_kph": 18,
            "gust_kph": 24,
            "lines": 2,
            "maneuverability": "high",
        }),
        ("Cervia", {
            "speed_kph": 26,
            "gust_kph": 31,
            "lines": 4,
            "maneuverability": "traction",
        }),
        ("Fano", {
            "speed_kph": 41,
            "gust_kph": 55,
            "lines": 1,
            "maneuverability": "static",
        }),
    ]
    print("%-12s %-9s %-13s %s" % ("STATION", "KITE", "SURFACE", "LINE TENSION"))
    for station, wind in stations:
        print(format_report(station, wind))


if __name__ == "__main__":
    main()

