            "wide vertical groove",
            "steep bass shelf",
        ],
    },
}

STYLUS_FORCES = {
    "microridge": (0.4, 1.4),
    "shibata": (0.5, 1.6),
    "elliptical": (0.7, 1.8),
    "conical_microgroove": (1.0, 2.0),
    "conical_transcription": (2.3, 4.0),
    "conical_shellac": (2.7, 5.0),
    "sapphire_ball": (3.4, 8.0),
}

REQUIRED_FIELDS = (
    "rpm",
    "groove_width_mil",
)


def _validate(master):
    missing = [field for field in REQUIRED_FIELDS if field not in master]
    if missing:
        raise ValueError("master is missing fields: " + ", ".join(missing))


def profile(master):
    _validate(master)
    rpm = float(master["rpm"])
    width = float(master["groove_width_mil"])
    scored = sorted(
        PRESSING_STANDARDS.items(),
        key=lambda item: (
            min(abs(rpm - speed) for speed in item[1]["speeds"]),
            abs(width - item[1]["groove_width_mil"]),
        ),
    )
    name, spec = scored[0]
    return (name, spec["equalization"])


def recommend_stylus(master):
    width = float(master["groove_width_mil"])
    name = min(
        STYLUS_FORCES,
        key=lambda tip: abs(STYLUS_FORCES[tip][0] - width * 0.9),
    )
    return (name, STYLUS_FORCES[name][1])


def describe(master):
    standard, equalization = profile(master)
    stylus, force = recommend_stylus(master)
    traits = PRESSING_STANDARDS[standard]["traits"]
    lines = [
        "{0}: {1} / {2}".format(master["title"], standard, equalization),
        "  stylus {0} tracking at {1:.1f} g".format(stylus, force),
        "  traits: " + "; ".join(traits),
    ]
    return "\n".join(lines)


def main():
