    if missing:
        raise KeyError("panel specification missing: " + ", ".join(missing))
    technique = choose_technique(panel)
    behaviors = ASSEMBLY_TECHNIQUES[technique]
    for wanted in behavior_priorities(panel):
        if wanted in behaviors:
            return (technique, wanted)
    return (technique, behaviors[0])


def format_advice(label, panel):
