    ]
    halftime_grid = [
        {"instrument": "snare", "step": 8, "waveform": "pulse"},
        {"instrument": "snare", "step": 24, "waveform": "pulse"},
        {"instrument": "hat", "step": 6, "waveform": "noise"},
