        "targets": [
            "complex carbohydrates",
            "starches",
            "glycogen",
        ],
        "organs": [
            "salivary glands",
            "pancreas",
            "small intestine",
        ],
        "optimal_ph": 7,
    },
    "protease": {
        "targets": [
            "dietary proteins",
            "polypeptides",
            "peptides",
        ],
        "organs": [
            "stomach",
            "pancreas",
            "intestinal lining",
        ],
        "optimal_ph": 2,
    },
    "lipase": {
        "targets": ["triglycerides", "dietary fats", "oils"],
        "organs": ["mouth", "stomach", "pancreas"],
        "optimal_ph": 8,
    },
    "nuclease": {
        "targets": ["dna", "rna", "nucleic acids"],
        "organs": ["pancreas", "small intestine", "liver"],
        "optimal_ph": 7,
    },
}


def _normalize(name):
    return " ".join(str(name).strip().lower().split())


def profile(organ):
    key = _normalize(organ)
    return sorted(
        enzyme
        for enzyme, data in ENZYMES.items()
        if key in data["organs"]
    )


def targets(enzyme):
    key = _normalize(enzyme)
    if key not in ENZYMES:
        raise KeyError("unknown digestive enzyme: {!r}".format(enzyme))
    return list(ENZYMES[key]["targets"])


def optimal_ph(enzyme):
    key = _normalize(enzyme)
    if key not in ENZYMES:
        raise KeyError("unknown digestive enzyme: {!r}".format(enzyme))
    return ENZYMES[key]["optimal_ph"]


def describe(enzyme):
    return "{} (pH {}) digests {}".format(
        _normalize(enzyme),
        optimal_ph(enzyme),
        ", ".join(targets(enzyme)),
    )


def main():
    organs = [
        "stomach",
        "pancreas",
        "small intestine",
        "mouth",
    ]
    for organ in organs:
        print("{}: {}".format(organ, ", ".join(profile(organ)) or "none"))
    print(targets("amylase"))
    for enzyme in sorted(ENZYMES):
        print(describe(enzyme))


if __name__ == "__main__":
