import collections
import re

def word_frequency(text):
    words = re.findall(
        pattern=r'\b\w+\b',
        string=text.lower(),
    )

    frequency_map = collections.defaultdict(
        int,
    )

    for word in words:
        frequency_map[word] += 1

    return dict(frequency_map)

