import os
import sys


def count_lines_in_file(filepath):
    """Return the number of lines in the file at filepath."""
    with open(
        filepath,
        'r',
        encoding='utf-8',
        errors='replace',
    ) as handle:
        return sum(1 for _ in handle)


def count_words_in_file(filepath):
    """Return the number of whitespace-separated words in the file."""
    with open(
        filepath,
        'r',
        encoding='utf-8',
        errors='replace',
    ) as handle:
        return sum(len(line.split()) for line in handle)


def file_stats(filepath):
    """Collect basic counts for a single file."""
    return {
        'path': filepath,
        'lines': count_lines_in_file(filepath),
        'words': count_words_in_file(filepath),
        'bytes': os.path.getsize(filepath),
    }


def collect_stats(filepaths):
    """Return stats dictionaries for every regular file given."""
    reports = []
    for filepath in filepaths:
        if os.path.isdir(filepath):
            print('skipping directory: {}'.format(filepath), file=sys.stderr)
            continue
        reports.append(file_stats(filepath))
    return reports


def format_table(reports):
    """Render the reports as an aligned text table with a totals row."""
    rows = [
        [
            'lines',
            'words',
            'bytes',
            'path',
        ],
    ]
    for report in reports:
        rows.append([
            str(report['lines']),
            str(report['words']),
            str(report['bytes']),
            report['path'],
        ])
    if len(reports) > 1:
        rows.append([
            str(sum(r['lines'] for r in reports)),
            str(sum(r['words'] for r in reports)),
            str(sum(r['bytes'] for r in reports)),
            'total',
        ])
    widths = [max(len(row[i]) for row in rows) for i in range(len(rows[0]))]
    lines = []
    for row in rows:
        cells = [cell.rjust(widths[i]) for i, cell in enumerate(row[:-1])]
        cells.append(row[-1])
        lines.append('  '.join(cells))
    return '\n'.join(lines)


def main(argv):
    paths = argv[1:]
    if not paths:
        print('usage: {} FILE [FILE ...]'.format(os.path.basename(argv[0])))
        return 2
    reports = collect_stats(paths)
    if not reports:
        return 1
    print(format_table(reports))
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv))

