RESPONSES = {
    "high": "Too high",
    "low": "Too low",
    "exact": "Correct!",
}

BOUNDS = {
    "minimum": 1,
    "maximum": 100,
}


def guess_number(secret_number, guess):
    """Compare a guess against the secret number and describe the result."""
    if guess > secret_number:
        return RESPONSES["high"]
    if guess < secret_number:
        return RESPONSES["low"]
    return RESPONSES["exact"]


def narrow_range(low, high, guess, verdict):
    """Shrink the candidate interval using the verdict for the given guess."""
    if verdict == RESPONSES["high"]:
        return low, guess - 1
    if verdict == RESPONSES["low"]:
        return guess + 1, high
    return guess, guess


def play_game(secret_number, guesses):
    """Run a whole game, returning one record per guess plus a summary."""
    low, high = BOUNDS["minimum"], BOUNDS["maximum"]
    rounds = []
    for number, guess in enumerate(guesses, start=1):
        verdict = guess_number(secret_number, guess)
        low, high = narrow_range(low, high, guess, verdict)
        rounds.append({
            "round": number,
            "guess": guess,
            "verdict": verdict,
            "remaining": (low, high),
        })
        if verdict == RESPONSES["exact"]:
            break
    return {
        "secret": secret_number,
        "rounds": rounds,
        "solved": bool(rounds) and rounds[-1]["verdict"] == RESPONSES["exact"],
    }


def format_report(game):
    """Turn a game result into printable lines."""
    lines = [
        "Secret number: %d" % game["secret"],
    ]
    for record in game["rounds"]:
        low, high = record["remaining"]
        lines.append(
            "  %d. guessed %3d -> %-9s (range %d-%d)"
            % (record["round"], record["guess"], record["verdict"], low, high)
        )
    lines.append("Result: %s" % ("solved" if game["solved"] else "not solved"))
    return lines


def main():
    sessions = [
        (10, [12, 10]),
        (42, [50, 25, 37, 43, 42]),
        (7, [1, 2, 3]),
    ]
    for secret, guesses in sessions:
        for line in format_report(play_game(secret, guesses)):
            print(line)
        print()


if __name__ == "__main__":
    main()

