def calculate_bmi(weight_kg, height_m):
    """Return the Body Mass Index for a weight in kg and a height in metres."""
    for label, value in (
        ("weight_kg", weight_kg),
        ("height_m", height_m),
    ):
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise TypeError("{} must be a number".format(label))
        if value <= 0:
            raise ValueError("{} must be positive".format(label))
    return round(weight_kg / (height_m ** 2), 2)


CATEGORIES = [
    (18.5, "Underweight"),
    (25.0, "Normal weight"),
    (30.0, "Overweight"),
    (float("inf"), "Obese"),
]


def classify_bmi(bmi):
    """Map a BMI value onto the standard WHO weight categories."""
    for upper, name in CATEGORIES:
        if bmi < upper:
            return name
    return CATEGORIES[-1][1]


def healthy_weight_range(height_m):
    """Return the (min, max) weight in kg giving a 'Normal weight' BMI."""
    return (
        round(18.5 * height_m ** 2, 1),
        round(24.9 * height_m ** 2, 1),
    )


def build_report(people):
    """Turn raw (name, weight, height) records into printable dictionaries."""
    report = []
    for name, weight_kg, height_m in people:
        bmi = calculate_bmi(weight_kg, height_m)
        low, high = healthy_weight_range(height_m)
        report.append({
            "name": name,
            "bmi": bmi,
            "category": classify_bmi(bmi),
            "healthy_range": "{}-{} kg".format(low, high),
        })
    return report


def format_row(entry):
    """Format a single report dictionary as a fixed-width table row."""
    return "{:<10}{:>7.2f}  {:<15}{}".format(
        entry["name"],
        entry["bmi"],
        entry["category"],
        entry["healthy_range"],
    )


def main():
    people = [
        ("Ada", 70, 1.75),
        ("Bo", 100, 2.0),
        ("Cleo", 45, 1.62),
        ("Dev", 95, 1.70),
    ]
    header = "{:<10}{:>7}  {:<15}{}".format(
        "Name",
        "BMI",
        "Category",
        "Healthy range",
    )
    print(header)
    print("-" * len(header))
    for entry in build_report(people):
        print(format_row(entry))


if __name__ == "__main__":
    main()

