def capitalize_sentences(text):
    sentences = []

    delimiters = [
        '.', 
        '!', 
        '?', 
    ]

    current_sentence_start = 0
    for i, char in enumerate(text):
        if char in delimiters:
            sentences.append(
                text[current_sentence_start : i + 1],
            )
            current_sentence_start = i + 1

    if current_sentence_start < len(text):
        sentences.append(
            text[current_sentence_start :],
        )

    capitalized_sentences = []
    for sentence in sentences:
        stripped_sentence = sentence.lstrip()
        if stripped_sentence:
            capitalized_sentences.append(
                stripped_sentence[0].upper() + stripped_sentence[1:],
            )
        else:
            capitalized_sentences.append(
                stripped_sentence,
            )

    return ''.join(
        capitalized_sentences,
    )

