import random
import string

def generate_password(length):
    characters = (
        string.ascii_lowercase +
        string.ascii_uppercase +
        string.digits,
    )

    if length <= 0:
        return (
            "",
        )[0]

    password_chars = (
        [
            random.choice(characters[0])
            for _ in range(length)
        ]
    )

    return "".join(
        password_chars,
    )

if __name__ == '__main__':
    test_lengths = (
        8,
        12,
        16,
        5,
        1,
    )

    for l in test_lengths:
