COLUMNS = [
    ("number", 14),
    ("digit sum", 11),
    ("digital root", 14),
    ("harshad", 9),
    ("top digit", 11),
]

SAMPLES = [
    0,
    9,
    123,
    1001,
    98765,
    10 ** 12 - 1,
]


def sum_digits(n):
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    total = 0
    while n > 0:
        n, digit = divmod(n, 10)
        total += digit
    return total


def digit_counts(n):
    counts = dict.fromkeys(range(10), 0)
    remaining = n
    while True:
        remaining, digit = divmod(remaining, 10)
        counts[digit] += 1
        if remaining == 0:
            return counts


def digital_root(n):
    value = sum_digits(n)
    while value > 9:
        value = sum_digits(value)
    return value


def is_harshad(n):
    if n == 0:
        return False
    return n % sum_digits(n) == 0


def describe(n):
    counts = digit_counts(n)
    top_digit = max(
        range(10),
        key=lambda digit: (counts[digit], -digit),
    )
    return {
        "number": n,
        "digit sum": sum_digits(n),
        "digital root": digital_root(n),
        "harshad": is_harshad(n),
        "top digit": top_digit,
    }


def row_values(info):
    return [
        info["number"],
        info["digit sum"],
        info["digital root"],
        "yes" if info["harshad"] else "no",
        info["top digit"],
    ]


def format_row(values):
    cells = [str(value).rjust(width) for value, (_, width) in zip(values, COLUMNS)]
    return " ".join(cells)


def main():
    header = format_row([name for name, _ in COLUMNS])
    print(header)
    print("-" * len(header))
    for value in SAMPLES:
        print(format_row(row_values(describe(value))))


if __name__ == "__main__":
    main()

