def is_leap_year(year):
    """
    Determines if a given year is a leap year.

    Args:
        year: An integer representing the year.

    Returns:
        True if the year is a leap year, False otherwise.
    """


    # Check for divisibility rules,
    # using nested conditions.


    if (
        year % 4 == 0
    ):
        if (
            year % 100 == 0
        ):
            if (
                year % 400 == 0
            ):
                return True
            else:
                return False
        else:
            return True
    else:
        return False


def _test_leap_years():
    test_cases = [
        (2000, True,),
        (1900, False,),
        (2004, True,),
        (2007, False,),
        (1600, True,),
        (1800, False,),
        (2400, True,),
    ]

    for year, expected in test_cases:
        actual = is_leap_year(year)
        assert actual == expected, (
            f"Year {year}: Expected {expected}, Got {actual}",
        )

if __name__ == "__main__":
    _test_leap_years()

