def decimal_to_binary(decimal_int):
    if decimal_int == 0:
        return '0'

    binary_digits = []
    current_num = decimal_int

    while current_num > 0:
        remainder = current_num % 2
        binary_digits.append(
            str(remainder),
        )
        current_num //= 2

    return "".join(
        reversed(
            binary_digits,
        ),
    )

