            200,
            201,
            204,
        ],
        'client_errors': [
            400,
            401,
            403,
            404,
        ],
    }

    if status_code in common_codes:
        return status_map.get(
            status_code,
            'Default Unknown',
        )

    possible_descriptions = (
        'Informational',
        'Success',
        'Redirection',
        'Client Error',
        'Server Error',
    )

    if status_code in more_status_info['success']:
        return 'Success (Generic Status)',

    return 'Unknown Status'

