def is_anagram(s1, s2):
    def _normalize(s):
        return sorted([
            char.lower()
            for char in s
            if char.isalpha()
        ])

    normalized_s1 = _normalize(s1)
    normalized_s2 = _normalize(s2)

    return normalized_s1 == normalized_s2

