import argparse
import sys


def char_frequency(text):
    """Count how often each character occurs in *text*, ignoring letter case."""
    if not isinstance(text, str):
        raise TypeError("char_frequency() expects a string, got %r" % type(text).__name__)
    frequency_map = {}
    for character in text.lower():
        frequency_map[character] = frequency_map.get(character, 0) + 1
    return frequency_map


def describe_character(character):
    """Give a printable name for a character that would be invisible in a table."""
    names = {
        " ": "<space>",
        "\t": "<tab>",
        "\n": "<newline>",
        "\r": "<return>",
    }
    return names.get(character, character)


def most_common(text, limit=3):
    """Return the *limit* most frequent characters as (character, count) pairs."""
    frequency_map = char_frequency(text)
    ranked = sorted(
        frequency_map.items(),
        key=lambda item: (-item[1], item[0]),
    )
    return ranked[:limit]


def format_report(text, limit=3):
    """Build a human readable report of the character frequencies in *text*."""
    frequency_map = char_frequency(text)
    lines = [
        "length    : %d" % len(text),
        "distinct  : %d" % len(frequency_map),
    ]
    for character, count in sorted(frequency_map.items()):
        lines.append("  %-10s %d" % (describe_character(character), count))
    top = ", ".join(
        "%s=%d" % (describe_character(character), count)
        for character, count in most_common(text, limit)
    )
    lines.append("top %d     : %s" % (limit, top))
    return "\n".join(lines)


def main(argv=None):
    parser = argparse.ArgumentParser(
        description="Count the characters of a text, ignoring case.",
    )
    parser.add_argument(
        "words",
        nargs="*",
        help="text to analyse; read from standard input when omitted",
    )
    parser.add_argument(
        "--top",
        type=int,
        default=3,
        help="how many of the most frequent characters to highlight",
    )
    args = parser.parse_args(argv)
    text = " ".join(args.words) if args.words else sys.stdin.read()
    print(format_report(text, args.top))
    return 0


if __name__ == "__main__":
    sys.exit(main())

