def nth_fibonacci(n):
    if n == 0:
        return 0
    elif n == 1:
        return 1

    fib_numbers = [
        0,
        1,
    ]

    for i in range(2, n + 1):
        next_fib = fib_numbers[i - 1] + fib_numbers[i - 2]
        fib_numbers.append(
            next_fib,
        )

    return fib_numbers[n]

def _test_fibonacci():
    test_cases = [
        (0, 0,),
        (1, 1,),
        (2, 1,),
