def is_valid_url(url: str) -> bool:
    schemes = [
        'http://',
        'https://',
    ]

    for scheme in schemes:
        if url.startswith(scheme):
            remaining_url = url[len(scheme):]
            if '.' in remaining_url:
                valid_prefixes = (
                    'www.',
                    'example.',
                    'test.',
                )
                if remaining_url.startswith(valid_prefixes):
                    return True
                return False
    return False

