"""Reverse the order of words in a sentence, keeping each word intact."""

import sys

SAMPLE_SENTENCES = [
    "hello world",
    "python is fun",
    "  spaced   out   words  ",
    "single",
]


def _validate(sentence):
    """Ensure the input really is a string before processing it."""
    if not isinstance(sentence, str):
        raise TypeError("sentence must be a str, got {0}".format(
            type(sentence).__name__,
        ))
    return sentence


def split_words(sentence):
    """Split on arbitrary runs of whitespace, dropping empty fragments."""
    return _validate(sentence).split()


def reverse_sentence_words(sentence):
    """Return the sentence with its word order reversed."""
    return " ".join(reversed(split_words(sentence)))


def describe(sentence):
    """Build a small record about one reversal."""
    words = split_words(sentence)
    return {
        "original": sentence,
        "reversed": reverse_sentence_words(sentence),
        "word_count": len(words),
        "longest": max(words, key=len) if words else "",
    }


def format_record(record):
    """Render a record produced by describe() as one text line."""
    fields = [
        "{0:>3} words".format(record["word_count"]),
        "original={0!r}".format(record["original"]),
        "reversed={0!r}".format(record["reversed"]),
        "longest={0!r}".format(record["longest"]),
    ]
    return " | ".join(fields)


def report(sentences):
    """Format a whole batch of sentences, one line each."""
    return "\n".join(format_record(describe(item)) for item in sentences)


def summarize(sentences):
    """Collect batch-wide totals for the trailing summary line."""
    return {
        "sentences": len(sentences),
        "words": sum(len(split_words(item)) for item in sentences),
    }


def main(argv=None):
    """Reverse the sentences given on the command line, or the samples."""
    sentences = list(sys.argv[1:] if argv is None else argv)
    if not sentences:
        sentences = SAMPLE_SENTENCES
    print(report(sentences))
    totals = summarize(sentences)
    print("{0} sentences, {1} words".format(
        totals["sentences"],
        totals["words"],
    ))


if __name__ == "__main__":
    main()

