def count_char(
    text,
    char_to_count,
):
    count = 0
    for char in text:
        if char == char_to_count:
            count += 1
    return count

def test_count_char():
    test_cases = [
        ('banana', 'a', 3,),
        ('Mississippi', 's', 4,),
        ('hello world', 'l', 3,),
        ('python', 'z', 0,),
        ('', 'a', 0,),
        ('aaaaa', 'a', 5,),
        ('AbcAbc', 'A', 2,),
