def merge_dicts(dict1, dict2):
    """Return a new dict with dict2's values overriding dict1's on shared keys."""
    if not isinstance(dict1, dict) or not isinstance(dict2, dict):
        raise TypeError("merge_dicts expects two dictionaries")
    merged = dict(dict1)
    merged.update(dict2)
    return merged


DEFAULT_CONFIG = {
    "host": "localhost",
    "port": 8000,
    "debug": False,
}

OVERRIDE_LAYERS = [
    {
        "port": 9000,
        "workers": 4,
    },
    {
        "debug": True,
        "log_level": "INFO",
    },
]


def merge_all(layers):
    """Fold a sequence of dictionaries left to right, later layers winning."""
    result = {}
    for layer in layers:
        result = merge_dicts(result, layer)
    return result


def conflicting_keys(dict1, dict2):
    """Keys present in both dicts whose values actually differ."""
    return sorted(key for key in dict1 if key in dict2 and dict1[key] != dict2[key])


def describe_merge(dict1, dict2):
    """Summarise what a merge of two dicts does, key by key."""
    return {
        "result": merge_dicts(dict1, dict2),
        "kept": sorted(key for key in dict1 if key not in dict2),
        "added": sorted(key for key in dict2 if key not in dict1),
        "overwritten": conflicting_keys(dict1, dict2),
    }


def format_report(summary):
    """Render a merge summary as human readable lines."""
    items = ", ".join(
        "{}={!r}".format(key, value) for key, value in sorted(summary["result"].items())
    )
    lines = [
        "kept from first : {}".format(", ".join(summary["kept"]) or "-"),
        "added by second : {}".format(", ".join(summary["added"]) or "-"),
        "overwritten     : {}".format(", ".join(summary["overwritten"]) or "-"),
        "merged          : {{{}}}".format(items),
    ]
    return "\n".join(lines)


def main():
    examples = [
        ({"a": 1, "b": 2}, {"b": 3, "c": 4}),
        ({"x": 10}, {"y": 20}),
    ]
    for first, second in examples:
        print("{} + {}".format(first, second))
        print(format_report(describe_merge(first, second)))
        print()

    print("effective configuration:")
    for key, value in sorted(merge_all([DEFAULT_CONFIG] + OVERRIDE_LAYERS).items()):
        print("  {} = {!r}".format(key, value))


if __name__ == "__main__":
    main()

