import random
from collections import Counter

STANDARD_DICE = [
    4,
    6,
    8,
    10,
    12,
    20,
]

DIE_NAMES = {
    4: "tetrahedron",
    6: "cube",
    8: "octahedron",
    10: "pentagonal trapezohedron",
    12: "dodecahedron",
    20: "icosahedron",
}


def roll_die(num_sides):
    """Return a random integer between 1 and num_sides inclusive."""
    if not isinstance(num_sides, int) or isinstance(num_sides, bool):
        raise TypeError("num_sides must be an int")
    if num_sides < 1:
        raise ValueError("num_sides must be at least 1")
    return random.randint(1, num_sides)


def roll_many(num_sides, times):
    """Roll one die repeatedly and return the list of results."""
    if times < 0:
        raise ValueError("times must be non-negative")
    return [roll_die(num_sides) for _ in range(times)]


def summarize(results, num_sides):
    """Build a small report describing a batch of rolls."""
    counts = Counter(results)
    return {
        "sides": num_sides,
        "rolls": len(results),
        "total": sum(results),
        "mean": sum(results) / len(results) if results else 0.0,
        "distribution": [counts.get(face, 0) for face in range(1, num_sides + 1)],
    }


def format_report(report):
    name = DIE_NAMES.get(report["sides"], "die")
    header = "d{sides} ({name}): {rolls} rolls, mean {mean:.2f}".format(
        name=name,
        **report,
    )
    bars = []
    for face, count in enumerate(report["distribution"], start=1):
        bars.append(
            "  {:>3}: {} {}".format(
                face,
                "#" * count,
                count,
            )
        )
    return "\n".join([header] + bars)


def main():
    random.seed(20260918)
    single_rolls = {
        sides: roll_die(sides)
        for sides in STANDARD_DICE
    }
    for sides, value in single_rolls.items():
        print("roll_die({}) -> {}".format(sides, value))
    print()
    for sides, times in [
        (6, 30),
        (20, 40),
    ]:
        print(format_report(summarize(roll_many(sides, times), sides)))
        print()


if __name__ == "__main__":
    main()

