def get_item_quantity(inventory, item_name):
    """Return the quantity of item_name in inventory, or 0 if absent."""
    return int(inventory.get(item_name, 0))


def format_report(inventory, watch_list):
    """Build a text report of the quantities of every watched item."""
    lines = [
        "{:<10} {:>5}".format("ITEM", "QTY"),
    ]
    for item_name in watch_list:
        lines.append(
            "{:<10} {:>5}".format(
                item_name,
                get_item_quantity(inventory, item_name),
            )
        )
    return "\n".join(lines)


def apply_shipment(inventory, shipment):
    """Add shipment amounts to inventory and return the updated dict."""
    updated = dict(inventory)
    for item_name, amount in shipment.items():
        updated[item_name] = get_item_quantity(updated, item_name) + amount
    return updated


def fulfil_order(inventory, order):
    """Ship what is available; return (updated inventory, shipped, missing)."""
    updated = dict(inventory)
    shipped = {}
    missing = {}
    for item_name, wanted in order.items():
        available = get_item_quantity(updated, item_name)
        taken = min(available, wanted)
        if taken:
            shipped[item_name] = taken
            updated[item_name] = available - taken
        if wanted > taken:
            missing[item_name] = wanted - taken
    return (
        updated,
        shipped,
        missing,
    )


def low_stock_items(inventory, threshold):
    """Names of items whose quantity is at or below threshold, sorted."""
    return sorted(
        [
            name
            for name in inventory
            if get_item_quantity(inventory, name) <= threshold
        ],
    )


def main():
    inventory = {
        'apple': 10,
        'banana': 5,
        'cherry': 2,
    }
    shipment = {
        'banana': 12,
        'date': 7,
    }
    order = {
        'apple': 4,
        'cherry': 3,
        'orange': 1,
    }
    print(get_item_quantity(inventory, 'apple'))
    print(get_item_quantity(inventory, 'orange'))

    inventory = apply_shipment(inventory, shipment)
    inventory, shipped, missing = fulfil_order(inventory, order)

    print("shipped:", shipped)
    print("missing:", missing)
    print(format_report(inventory, sorted(inventory) + ['orange']))
    print("low stock:", low_stock_items(inventory, 2))


if __name__ == '__main__':
    main()

