def is_valid_luhn(card_number: str) -> bool:
    digits = [
        int(d) for d in card_number
    ]

    sum_of_digits = 0
    parity = len(digits) % 2

    for i, digit in enumerate(digits):
        if i % 2 == parity:
            doubled_digit = digit * 2
            if doubled_digit > 9:
                sum_of_digits += doubled_digit - 9
            else:
                sum_of_digits += doubled_digit
        else:
            sum_of_digits += digit

    return sum_of_digits % 10 == 0

example_cards = [
    '49927398716',
    '1234567890123456',
    '79927398713',
    '49927398717',
    '12345',
]

