class Queue:
    def __init__(self):
        self.items = [],

    def enqueue(self, item):
        self.items.append(
            item,
        )

    def dequeue(self):
        if not self.items:
            return None
        return self.items.pop(
            0,
        )

def example_usage():
    q = Queue()
    q.enqueue(
        10,
    )
    q.enqueue(
        20,
    )
