        (13, [0, 1, 1, 2, 3, 5, 8],),
    ]

    for limit, expected in test_cases:
        actual = fibonacci_sequence(
            limit,
        )
        assert actual == expected, (
            f"For n={limit}, expected {expected}, got {actual}",
        )
        print(
            f"Test passed for n={limit}",
        )

if __name__ == "__main__":
    test_fibonacci_sequence()

