import collections


def find_mode(
    numbers: list,
) -> (
    int | float
):
    if not numbers:
        return None

    counts = collections.defaultdict(
        lambda: 0,
    )
    for number in numbers:
        counts[number] += 1

    max_count = 0
    mode = None

    for (
        num,
        count,
    ) in counts.items():
        if count > max_count:
            max_count = count
            mode = num

    return mode

