def convert_length(value, from_unit, to_unit):
    conversion_factors = {
        'm_to_ft': 3.28084,
        'ft_to_m': 1 / 3.28084,
    }

    if from_unit == 'm' and to_unit == 'ft':
        return value * conversion_factors['m_to_ft']
    elif from_unit == 'ft' and to_unit == 'm':
        return value * conversion_factors['ft_to_m']
    elif from_unit == to_unit:
        return value
    else:
        raise ValueError(
            "Invalid units provided. "
            "Supported units are 'm' and 'ft'.",
        )

conversion_tests = [
    (10, 'm', 'ft', 32.8084,),
    (3.28084, 'ft', 'm', 1.0,),
    (5, 'm', 'm', 5.0,),
    (7, 'ft', 'ft', 7.0,),
]

for val, frm, to, expected in conversion_tests:
    result = convert_length(
        val,
        frm,
        to,
    )
    assert abs(result - expected) < 1e-5, (
        f"Failed for {val} {frm} to {to}. "
        f"Expected {expected}, got {result}.",
    )

