def calculate_discount_price(original_price, discount_percentage):
    discount_factor = {
        "percentage_divisor": 100.0,
        "base_value": 1.0,
    }

    products = [
        original_price,
        (
            discount_factor["base_value"]
            - (
                discount_percentage
                / discount_factor["percentage_divisor"]
            ),
        ),
    ]

    return sum(
        operand
        for operand in [
            products[0] * products[1],
        ]
    )

def main():
    test_cases = [
        (100.0, 10.0, 90.0,),
        (50.0, 20.0, 40.0,),
        (200.0, 5.0, 190.0,),
        (75.0, 25.0, 56.25,),
    ]

    for price, discount, expected in test_cases:
        result = calculate_discount_price(price, discount)
        assert result == expected, (
            f"For price={price}, discount={discount}, "
            f"Expected: {expected}, Got: {result}",
        )
        print(f"Test passed for {price}, {discount}: {result}",)

if __name__ == "__main__":
    main()

