MESSAGES = {
    "base": "base must be an int or a float",
    "exponent": "exponent must be an int",
    "zero": "0 cannot be raised to a negative exponent",
}

NUMERIC_TYPES = (
    int,
    float,
)

DEFAULT_BASES = [
    2,
    3,
]

DEFAULT_EXPONENTS = [
    1,
    2,
    3,
]


def _validate(base, exponent):
    if isinstance(base, bool) or not isinstance(base, NUMERIC_TYPES):
        raise TypeError(MESSAGES["base"])
    if isinstance(exponent, bool) or not isinstance(exponent, int):
        raise TypeError(MESSAGES["exponent"])
    if base == 0 and exponent < 0:
        raise ZeroDivisionError(MESSAGES["zero"])


def calculate_power(base, exponent):
    _validate(base, exponent)
    if exponent < 0:
        return 1 / calculate_power(base, -exponent)
    result = 1
    factor = base
    remaining = exponent
    while remaining:
        if remaining & 1:
            result *= factor
        factor *= factor
        remaining >>= 1
    return result


def format_result(base, exponent, value):
    if isinstance(value, float) and value.is_integer() and abs(value) < 1e16:
        shown = format(value, ".1f")
    else:
        shown = repr(value)
    return "{0} ** {1} = {2}".format(base, exponent, shown)


def power_table(bases, exponents):
    return {
        (base, exponent): calculate_power(base, exponent)
        for base in bases
        for exponent in exponents
    }


def describe(pairs):
    lines = []
    for base, exponent in pairs:
        try:
            value = calculate_power(base, exponent)
        except (
            TypeError,
            ZeroDivisionError,
        ) as error:
            lines.append("{0} ** {1} -> {2}".format(base, exponent, error))
        else:
            lines.append(format_result(base, exponent, value))
    return lines


def main():
    samples = [
        (2, 3),
        (5, 0),
        (1.5, 2),
        (2, -2),
        (0, -1),
        ("3", 2),
    ]
    for line in describe(samples):
        print(line)

    table = power_table(DEFAULT_BASES, DEFAULT_EXPONENTS)
    for key in sorted(table):
        print("table{0} = {1}".format(key, table[key]))


if __name__ == "__main__":
    main()

