HEX_DIGITS = frozenset("0123456789abcdefABCDEF")

NAMED_COLORS = {
    "#000000": "black",
    "#ffffff": "white",
    "#ff0000": "red",
    "#00ff00": "lime",
    "#0000ff": "blue",
}


def is_valid_hex_color(code):
    """Return True if code is a valid 3- or 6-digit hex color code."""
    if not isinstance(code, str):
        return False
    if not code.startswith("#"):
        return False
    body = code[1:]
    if len(body) not in (3, 6):
        return False
    return all(ch in HEX_DIGITS for ch in body)


def expand_shorthand(code):
    """Turn '#abc' into '#aabbcc'; leave 6-digit codes unchanged."""
    if not is_valid_hex_color(code):
        raise ValueError("not a valid hex color: {!r}".format(code))
    body = code[1:]
    if len(body) == 3:
        body = "".join(ch * 2 for ch in body)
    return "#" + body.lower()


def to_rgb(code):
    """Return the (red, green, blue) channel values of a hex color."""
    body = expand_shorthand(code)[1:]
    return (
        int(body[0:2], 16),
        int(body[2:4], 16),
        int(body[4:6], 16),
    )


def describe(code):
    """Build a dictionary summarising a single candidate color code."""
    if not is_valid_hex_color(code):
        return {
            "input": code,
            "valid": False,
        }
    normalized = expand_shorthand(code)
    return {
        "input": code,
        "valid": True,
        "normalized": normalized,
        "rgb": to_rgb(code),
        "name": NAMED_COLORS.get(normalized, "-"),
    }


def format_row(summary):
    """Render one summary dictionary as a single aligned text line."""
    if not summary["valid"]:
        return "{:<10} invalid".format(summary["input"])
    red, green, blue = summary["rgb"]
    return "{:<10} {:<9} rgb({:>3}, {:>3}, {:>3}) {}".format(
        summary["input"],
        summary["normalized"],
        red,
        green,
        blue,
        summary["name"],
    )


def main():
    candidates = [
        "#ABC",
        "#123456",
        "#GGGGGG",
        "#fff",
        "123456",
        "#12345",
        "#00F",
    ]
    for code in candidates:
        print(format_row(describe(code)))
    accepted = [code for code in candidates if is_valid_hex_color(code)]
    print("{} of {} codes accepted".format(len(accepted), len(candidates)))


if __name__ == "__main__":
    main()

