def count_set_bits(n):
    """Return the number of '1' bits in the binary representation of n."""
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("count_set_bits() requires a non-negative integer")
    if n < 0:
        raise ValueError("count_set_bits() requires a non-negative integer")
    count = 0
    while n:
        n &= n - 1
        count += 1
    return count


def bit_positions(n):
    """Return the indices of the set bits of n, least significant first."""
    positions = []
    index = 0
    while n:
        if n & 1:
            positions.append(index)
        n >>= 1
        index += 1
    return positions


def parity_label(n):
    """Return 'even' or 'odd' according to the popcount parity of n."""
    labels = {
        0: "even",
        1: "odd",
    }
    return labels[count_set_bits(n) & 1]


def describe(n):
    """Build a record summarising the binary structure of n."""
    return {
        "value": str(n),
        "binary": format(n, "b"),
        "ones": str(count_set_bits(n)),
        "positions": ",".join(str(p) for p in bit_positions(n)),
        "parity": parity_label(n),
    }


def format_row(record):
    fields = [
        record["value"].rjust(6),
        record["binary"].rjust(12),
        record["ones"].rjust(4),
        record["positions"].ljust(14),
        record["parity"].ljust(5),
    ]
    return " | ".join(fields)


def report(numbers):
    header = format_row({
        "value": "n",
        "binary": "binary",
        "ones": "ones",
        "positions": "positions",
        "parity": "par",
    })
    lines = [
        header,
        "-" * len(header),
    ]
    for n in numbers:
        lines.append(format_row(describe(n)))
    return "\n".join(lines)


def main():
    samples = [
        0,
        7,
        10,
        255,
        1024,
        123456789,
    ]
    print(report(samples))
    print("total set bits:", sum(count_set_bits(n) for n in samples))


if __name__ == "__main__":
    main()

