"""Utilities for merging pre-sorted numeric sequences."""

SAMPLE_PAIRS = [
    ([1, 3, 5], [2, 4, 6]),
    ([10], []),
    ([], []),
    ([1, 1, 2], [1, 3]),
    ([-5.5, 0, 0.5], [-1, 2]),
]

SAMPLE_BATCH = [
    [1, 4, 9],
    [2, 3],
    [5, 6, 7, 8],
]


def _validate_sorted(values, name):
    if not isinstance(values, (list, tuple)):
        raise TypeError(
            f"{name} must be a list or tuple, got {type(values).__name__}",
        )
    for index, item in enumerate(values):
        if isinstance(item, bool) or not isinstance(item, (int, float)):
            raise TypeError(
                f"{name}[{index}] is not a number: {item!r}",
            )
    for index in range(1, len(values)):
        if values[index] < values[index - 1]:
            raise ValueError(
                f"{name} is not sorted at position {index}: "
                f"{values[index - 1]!r} > {values[index]!r}",
            )
    return list(values)


def merge_sorted_lists(list1, list2):
    left = _validate_sorted(list1, "list1")
    right = _validate_sorted(list2, "list2")
    merged = []
    i = j = 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:
            merged.append(left[i])
            i += 1
        else:
            merged.append(right[j])
            j += 1
    merged.extend(left[i:])
    merged.extend(right[j:])
    return merged


def merge_many(lists):
    result = []
    for current in lists:
        result = merge_sorted_lists(result, current)
    return result


def merge_report(list1, list2):
    merged = merge_sorted_lists(list1, list2)
    return {
        "left": list(list1),
        "right": list(list2),
        "merged": merged,
        "length": len(merged),
        "span": (merged[0], merged[-1]) if merged else None,
    }


def format_report(report):
    span = report["span"]
    span_text = f"{span[0]} .. {span[1]}" if span else "empty"
    return " | ".join([
        f"{report['left']} + {report['right']}",
        f"-> {report['merged']}",
        f"n={report['length']}",
        f"span={span_text}",
    ])


def main():
    for left, right in SAMPLE_PAIRS:
        print(format_report(merge_report(left, right)))
    print("merge_many:", merge_many(SAMPLE_BATCH))


if __name__ == "__main__":
    main()

