def calculate_factorial(n):
    """Return n! for a non-negative integer n, computed iteratively."""
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("factorial is defined for integers only")
    if n < 0:
        raise ValueError("factorial is undefined for negative integers")
    result = 1
    for factor in range(2, n + 1):
        result *= factor
    return result


SMALL_FACTORIALS = {
    0: 1,
    1: 1,
    2: 2,
    3: 6,
    4: 24,
    5: 120,
}


def factorial_sequence(limit):
    """Return the list of factorials from 0! up to limit! inclusive."""
    return [calculate_factorial(n) for n in range(limit + 1)]


def binomial(n, k):
    """Number of ways to choose k items out of n, built from factorials."""
    if k < 0 or k > n:
        return 0
    return calculate_factorial(n) // (
        calculate_factorial(k) * calculate_factorial(n - k)
    )


def describe(n):
    """Build a small record describing n! and a couple of derived values."""
    value = calculate_factorial(n)
    return {
        "n": n,
        "factorial": value,
        "digits": len(str(value)),
        "middle_binomial": binomial(n, n // 2),
    }


def format_row(record):
    fields = [
        "{:>3}".format(record["n"]),
        "{:>24}".format(record["factorial"]),
        "{:>7}".format(record["digits"]),
        "{:>10}".format(record["middle_binomial"]),
    ]
    return " | ".join(fields)


def report(numbers):
    header = format_row({
        "n": "n",
        "factorial": "n!",
        "digits": "digits",
        "middle_binomial": "C(n,n/2)",
    })
    lines = [
        header,
        "-" * len(header),
    ]
    for n in numbers:
        lines.append(format_row(describe(n)))
    return "\n".join(lines)


def main():
    print(report([0, 1, 5, 10, 20]))
    print()
    print("first factorials:", factorial_sequence(6))
    mismatches = [
        n for n, expected in SMALL_FACTORIALS.items()
        if calculate_factorial(n) != expected
    ]
    if mismatches:
        raise AssertionError("bad factorials for {}".format(mismatches))


if __name__ == "__main__":
    main()

