    360,
]


def find_divisors(n):
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer")
    if n < 1:
        raise ValueError("n must be a positive integer")
    small = []
    large = []
    step = 1
    while step * step <= n:
        if n % step == 0:
            small.append(step)
            partner = n // step
            if partner != step:
                large.append(partner)
        step += 1
    large.reverse()
    return small + large


def prime_factors(n):
    factors = {}
    remaining = n
    for candidate in find_divisors(n)[1:]:
        while remaining % candidate == 0:
            factors[candidate] = factors.get(candidate, 0) + 1
            remaining //= candidate
        if remaining == 1:
            break
    return factors


def classify(n):
    divisors = find_divisors(n)
    aliquot = sum(divisors) - n
    if n == 1:
        kind = "unit"
    elif len(divisors) == 2:
        kind = "prime"
    elif aliquot > n:
        kind = "abundant"
    elif aliquot == n:
        kind = "perfect"
    else:
        kind = "deficient"
    return {
        "number": n,
        "divisors": divisors,
        "aliquot_sum": aliquot,
        "kind": kind,
        "factorization": prime_factors(n),
    }


