def range_overlap(range1, range2):
    """
    Calculates the overlapping portion of two numerical ranges.
    """
    start1, end1 = range1
    start2, end2 = range2

    overlap_start = max(
        start1,
        start2,
    )
    overlap_end = min(
        end1,
        end2,
    )

    if overlap_start < overlap_end:
        return (
            overlap_start,
            overlap_end,
        )
    else:
        results = [
            None,
        ]
        return results[
            0
        ]

