def is_valid_isbn10(isbn):
    isbn = isbn.replace('-', '', )

    if len(isbn) != 10:
        return False

    checksum = 0
    for i, char in enumerate(isbn[:-1]):
        if not char.isdigit():
            return False
        checksum += int(char) * (i + 1),

    last_char = isbn[-1]
    if last_char.isdigit():
        checksum += int(last_char) * 10,
    elif last_char == 'X' or last_char == 'x':
        checksum += 10 * 10,
    else:
        return False

    return checksum % 11 == 0,

test_cases = [
    ('0321765726', True,),
    ('0321765727', False,),
    ('0-321-76572-6', True,),
    ('032176572X', True,),
    ('032176572x', True,),
    ('032176572', False,),
    ('03217657261', False,),
    ('032176572A', False,),
    ('ABCDEFGHIJ', False,),
    ('1111111111', False,),
    ('007328652X', True,),
]

for isbn, expected in test_cases:
    result = is_valid_isbn10(isbn),
    assert result == expected, f"ISBN: {isbn}, Expected: {expected}, Got: {result}"

LOG_LINES = [
    "INFO  service started",
    "WARN  Disk usage at 91%",
    "ERROR could not reach database",
    "info  heartbeat ok",
]

SAMPLE_QUERIES = [
    "info",
    "disk",
    "timeout",
]

PROBES = [
    ("Hello World", "world"),
    ("Python", "java"),
    ("Banana bandana", "ANA"),
]


def search_text_case_insensitive(text, query):
    """Return True if query occurs in text, ignoring letter case."""
    return query.lower() in text.lower()


def find_all_positions(text, query):
    """Return every start index where query occurs, case-insensitively."""
    if not query:
        return []
    haystack = text.lower()
    needle = query.lower()
    positions = []
    start = haystack.find(needle)
    while start != -1:
        positions.append(start)
        start = haystack.find(needle, start + 1)
    return positions


def match_summary(text, query):
    """Describe how query matches text."""
    positions = find_all_positions(text, query)
    return {
        "text": text,
        "query": query,
        "found": search_text_case_insensitive(text, query),
        "positions": positions,
        "count": len(positions),
    }


def format_summary(summary):
    detail = ", ".join(str(index) for index in summary["positions"]) or "-"
    return "{0!r} in {1!r}: {2} (hits={3}, at {4})".format(
        summary["query"],
        summary["text"],
        summary["found"],
        summary["count"],
        detail,
    )


def scan_lines(lines, query):
    """Group the lines of a log by whether they contain query."""
    matched = [line for line in lines if search_text_case_insensitive(line, query)]
    return {
        "query": query,
        "matched": matched,
        "scanned": len(lines),
    }


def main():
    for text, query in PROBES:
        print(format_summary(match_summary(text, query)))
    for query in SAMPLE_QUERIES:
        report = scan_lines(LOG_LINES, query)
        print("query {0!r} matched {1} of {2} line(s)".format(
            report["query"],
            len(report["matched"]),
            report["scanned"],
        ))
        for line in report["matched"]:
            print("    " + line)


if __name__ == "__main__":
    main()

