import collections

def calculate_mode(data):
    if not data:
        return []

    counts = collections.Counter(
        data,
    )

    max_count = 0
    if counts:
        max_count = max(
            counts.values(),
        )

    modes = []
    for number, count in counts.items():
        if count == max_count:
            modes.append(
                number,
            )

    return sorted(
        modes,
    )

