def reverse_integer(
    num,
):
    sign = -1 if num < 0 else 1

    num_str = str(
        abs(num),
    )
    reversed_str = num_str[::-1]

    reversed_num = int(
        reversed_str,
    )

    return (
        sign
        * reversed_num,
    )

