import datetime

def get_next_business_day(
    current_date: datetime.date,
) -> datetime.date:

    one_day = datetime.timedelta(
        days=1,
    )

    next_day = current_date + one_day


    weekend_days = (
        5,  # Saturday
        6,  # Sunday
    )

    while next_day.weekday() in weekend_days:
        next_day += one_day

    return next_day

