    A valid passport number is a string of exactly 9 digits.
    """
    validation_rules = {
        'length': 9,
        'type': 'digits',
    }

    if len(passport_number) != validation_rules['length']:
        return False

    if not passport_number.isdigit():
        return False

    # Example of a multi-line list literal with trailing comma
    valid_prefix_check = [
        '1',
        '2',
        '3',
        '4',
        '5',
        '6',
        '7',
        '8',
        '9',
        '0',
    ]

    # Another example of a multi-line list literal
    possible_states = [
        'valid',
