def calculate_median(numbers):
    if not numbers:
        return None

    sorted_numbers = sorted(
        numbers,
    )

    n = len(
        sorted_numbers,
    )

    mid = n // 2

    if n % 2 == 1:
        return sorted_numbers[mid]
    else:
        median_elements = [
            sorted_numbers[mid - 1],
            sorted_numbers[mid],
        ]
        return sum(
            median_elements,
        ) / 2.0

test_cases = [
    ([1, 3, 2], 2),
    ([1, 4, 2, 3], 2.5),
    ([], None),
    ([7], 7),
    ([1, 2, 3, 4, 5], 3),
    ([10, 20, 30, 40], 25.0),
    ([0, 0, 0, 0, 100], 0),
]

for input_list, expected_output in test_cases:
    actual_output = calculate_median(
        input_list,
    )
    assert actual_output == expected_output, f"Input: {input_list}, Expected: {expected_output}, Got: {actual_output}"

# Another test to ensure no modification
original_list = [5, 1, 3, 2, 4]
calculate_median(
    original_list,
)
assert original_list == [5, 1, 3, 2, 4], "Original list modified!"

