from fractions import Fraction


def _validate(a, r, n):
    for name, value in (
        ("a", a),
        ("r", r),
        ("n", n),
    ):
        if isinstance(value, bool) or not isinstance(value, (int, float, Fraction)):
            raise TypeError("{} must be a real number, got {!r}".format(name, value))
    if not isinstance(n, int):
        raise TypeError("n must be an integer number of terms")
    if n < 0:
        raise ValueError("n must be non-negative")


def geometric_series_sum(a, r, n):
    """Return the sum of the first n terms of a + a*r + a*r**2 + ..."""
    _validate(a, r, n)
    if n == 0:
        return 0
    if r == 1:
        return a * n
    numerator = a * (r ** n - 1)
    denominator = r - 1
    if isinstance(numerator, int) and isinstance(denominator, int) and numerator % denominator == 0:
        return numerator // denominator
    return numerator / denominator


def geometric_terms(a, r, n):
    """Return the individual terms of the series as a list."""
    _validate(a, r, n)
    terms = []
    current = a
    for _ in range(n):
        terms.append(current)
        current = current * r
    return terms


def series_report(a, r, n):
    """Build a dictionary describing the series and its sum."""
    return {
        "first_term": a,
        "ratio": r,
        "count": n,
        "terms": geometric_terms(a, r, n),
        "sum": geometric_series_sum(a, r, n),
        "degenerate": r == 1,
    }


def format_report(report):
    joined = " + ".join(str(term) for term in report["terms"]) or "0"
    lines = [
        "a={first_term}, r={ratio}, n={count}".format(**report),
        "{} = {}".format(joined, report["sum"]),
    ]
    if report["degenerate"]:
        lines.append("ratio 1: sum is simply a * n")
    return "\n".join(lines)


def summary_table(cases):
    """Render a small aligned table of the sums for the given cases."""
    header = [
        "a",
        "r",
        "n",
        "sum",
    ]
    rows = [header]
    for a, r, n in cases:
        rows.append([
            str(a),
            str(r),
            str(n),
            str(geometric_series_sum(a, r, n)),
        ])
    widths = [max(len(row[i]) for row in rows) for i in range(len(header))]
    return "\n".join(
        "  ".join(cell.ljust(width) for cell, width in zip(row, widths)).rstrip()
        for row in rows
    )


def main():
    cases = [
        (1, 2, 3),
        (5, 1, 4),
        (3, Fraction(1, 2), 5),
        (2, -3, 4),
        (7, 4, 0),
    ]
    for a, r, n in cases:
        print(format_report(series_report(a, r, n)))
        print("-" * 40)
    print(summary_table(cases))


if __name__ == "__main__":
    main()

