PROJECT_TASKS = [
    {'name': 'A', 'dependencies': []},
    {'name': 'B', 'dependencies': ['A']},
    {'name': 'C', 'dependencies': ['A', 'B']},
    {'name': 'D', 'dependencies': ['C', 'E']},
]

SCENARIOS = [
    ('B', ['A']),
    ('B', []),
    ('C', ['A']),
    ('D', ['A', 'B', 'C']),
]


def build_index(tasks):
    index = {}
    for task in tasks:
        name = task['name']
        if name in index:
            raise ValueError('duplicate task name: %s' % name)
        index[name] = list(task.get('dependencies', []))
    return index


def unmet_dependencies(task_name, tasks, completed_tasks):
    index = build_index(tasks)
    if task_name not in index:
        raise KeyError('unknown task: %s' % task_name)
    done = set(completed_tasks)
    return [dep for dep in index[task_name] if dep not in done]


def has_unmet_dependencies(task_name, tasks, completed_tasks):
    return bool(unmet_dependencies(task_name, tasks, completed_tasks))


def missing_definitions(tasks):
    index = build_index(tasks)
    missing = set()
    for deps in index.values():
        for dep in deps:
            if dep not in index:
                missing.add(dep)
    return sorted(missing)


def runnable_tasks(tasks, completed_tasks):
    done = set(completed_tasks)
    return [
        task['name']
        for task in tasks
        if task['name'] not in done
        and not has_unmet_dependencies(task['name'], tasks, completed_tasks)
    ]


def summarize(tasks, completed_tasks):
    done = set(completed_tasks)
    return {
        'done': [task['name'] for task in tasks if task['name'] in done],
        'ready': runnable_tasks(tasks, completed_tasks),
        'blocked': [
            task['name']
            for task in tasks
            if task['name'] not in done
            and has_unmet_dependencies(task['name'], tasks, completed_tasks)
        ],
    }


def format_report(tasks, completed_tasks):
    lines = [
        '%-8s %s' % ('TASK', 'STATUS'),
    ]
    for task in tasks:
        name = task['name']
        blockers = unmet_dependencies(name, tasks, completed_tasks)
        if name in completed_tasks:
            status = 'done'
        elif blockers:
            status = 'blocked by ' + ', '.join(blockers)
        else:
            status = 'ready'
        lines.append('%-8s %s' % (
            name,
            status,
        ))
    undefined = missing_definitions(tasks)
    if undefined:
        lines.append('undefined dependencies: ' + ', '.join(undefined))
    return '\n'.join(lines)


def main():
    for task_name, completed in SCENARIOS:
        print('%s with %r -> %s' % (
            task_name,
            completed,
            has_unmet_dependencies(task_name, PROJECT_TASKS, completed),
        ))
    print(format_report(PROJECT_TASKS, ['A', 'B']))
    summary = summarize(PROJECT_TASKS, ['A', 'B'])
    for label in ('done', 'ready', 'blocked'):
        print('%s: %s' % (label, ', '.join(summary[label]) or '-'))


if __name__ == '__main__':
    main()

