def get_average_movie_rating(movie_ratings):
    averages = {}
    for title, ratings in movie_ratings.items():
        if ratings:
            averages[title] = sum(ratings) / len(ratings)
        else:
            averages[title] = 0.0
    return averages


def validate_ratings(movie_ratings):
    problems = []
    for title, ratings in movie_ratings.items():
        if not isinstance(title, str) or not title.strip():
            problems.append(
                "movie title must be a non-empty string, got {!r}".format(title),
            )
        if not isinstance(ratings, (list, tuple)):
            problems.append(
                "ratings for {!r} must be a list, got {}".format(title, type(ratings).__name__),
            )
            continue
        for rating in ratings:
            if isinstance(rating, bool) or not isinstance(rating, (int, float)):
                problems.append(
                    "rating {!r} for {!r} is not a number".format(rating, title),
                )
            elif not 0 <= rating <= 10:
                problems.append(
                    "rating {!r} for {!r} is outside 0..10".format(rating, title),
                )
    return problems


def rank_movies(averages):
    return sorted(
        averages.items(),
        key=lambda item: (-item[1], item[0]),
    )


def summarize(movie_ratings):
    averages = get_average_movie_rating(movie_ratings)
    rated = [value for value in averages.values() if value > 0.0]
    return {
        "averages": averages,
        "ranking": rank_movies(averages),
        "unrated": sorted(t for t, r in movie_ratings.items() if not r),
        "overall": sum(rated) / len(rated) if rated else 0.0,
    }


def format_report(summary):
    lines = ["Movie ratings report", "-" * 20]
    for position, (title, average) in enumerate(summary["ranking"], start=1):
        lines.append("{:>2}. {:<12} {:.2f}".format(position, title, average))
    lines.extend([
        "-" * 20,
        "Overall average of rated movies: {:.2f}".format(summary["overall"]),
        "Movies without ratings: {}".format(", ".join(summary["unrated"]) or "none"),
    ])
    return "\n".join(lines)


def main():
    catalogue = {
        "Movie A": [5, 4, 5],
        "Movie B": [3, 2],
        "Movie C": [],
        "Movie D": [10],
    }
    problems = validate_ratings(catalogue)
    if problems:
        for problem in problems:
            print("warning: " + problem)
    print(format_report(summarize(catalogue)))


if __name__ == "__main__":
    main()

