def calculate_triangle_perimeter(side1, side2, side3):
    """Return the perimeter of a triangle with the three given side lengths."""
    sides = [
        side1,
        side2,
        side3,
    ]
    for side in sides:
        if not isinstance(side, (int, float)) or isinstance(side, bool):
            raise TypeError("side lengths must be int or float")
        if side <= 0:
            raise ValueError("side lengths must be positive")
    longest = max(sides)
    if 2 * longest >= sum(sides):
        raise ValueError("sides do not satisfy the triangle inequality")
    return sum(sides)


def classify_triangle(side1, side2, side3):
    """Return 'equilateral', 'isosceles' or 'scalene' for the given sides."""
    distinct = {
        round(float(side1), 9),
        round(float(side2), 9),
        round(float(side3), 9),
    }
    names = {
        1: "equilateral",
        2: "isosceles",
        3: "scalene",
    }
    return names[len(distinct)]


def describe_triangle(side1, side2, side3):
    """Bundle the measurements of one triangle into a dictionary."""
    perimeter = calculate_triangle_perimeter(side1, side2, side3)
    return {
        "sides": (side1, side2, side3),
        "perimeter": perimeter,
        "kind": classify_triangle(side1, side2, side3),
        "longest_side": max(side1, side2, side3),
    }


def format_row(description):
    """Render one triangle description as a single aligned text row."""
    sides = " + ".join(format(side, "g") for side in description["sides"])
    columns = [
        sides.ljust(20),
        format(description["perimeter"], "g").rjust(8),
        description["kind"].rjust(12),
    ]
    return " | ".join(columns)


def build_report(triangles):
    """Return the report lines for a sequence of side triples."""
    lines = [
        format_row(describe_triangle(*triangle)) for triangle in triangles
    ]
    total = sum(calculate_triangle_perimeter(*triangle) for triangle in triangles)
    lines.append("total perimeter: " + format(total, "g"))
    return lines


def main():
    triangles = [
        (3, 4, 5),
        (7.5, 6, 8.5),
        (2, 2, 2),
        (5, 5, 8),
    ]
    for line in build_report(triangles):
        print(line)
    print(calculate_triangle_perimeter(3, 4, 5))
    print(calculate_triangle_perimeter(7.5, 6, 8.5))


if __name__ == "__main__":
    main()

