COLUMNS = [
    {
        "key": "binary",
        "label": "BINARY",
    },
    {
        "key": "gray",
        "label": "GRAY",
    },
    {
        "key": "value",
        "label": "VALUE",
    },
]


def _validate(bits: str) -> str:
    if not bits:
        raise ValueError("empty string is not a binary number")
    bad = sorted(set(bits) - {"0", "1"})
    if bad:
        raise ValueError("invalid binary digits: " + ", ".join(bad))
    return bits


def binary_to_gray(binary: str) -> str:
    bits = _validate(binary)
    gray = [
        bits[0],
    ]
    for previous, current in zip(bits, bits[1:]):
        gray.append("1" if previous != current else "0")
    return "".join(gray)


def describe(binary: str) -> dict:
    return {
        "binary": binary,
        "gray": binary_to_gray(binary),
        "value": int(binary, 2),
    }


def binary_words(width: int) -> list:
    if width < 1:
        raise ValueError("width must be positive")
    return [format(value, "0{}b".format(width)) for value in range(2**width)]


def format_report(samples) -> str:
    rows = [
        [column["label"] for column in COLUMNS],
    ]
    for sample in samples:
        info = describe(sample)
        rows.append([str(info[column["key"]]) for column in COLUMNS])
    widths = [max(len(row[index]) for row in rows) for index in range(len(COLUMNS))]
    lines = []
    for row in rows:
        cells = [cell.ljust(widths[index]) for index, cell in enumerate(row)]
        lines.append("  ".join(cells).rstrip())
    return "\n".join(lines)


def main() -> None:
    sections = [
        ("Examples", ["000", "1011", "11110000"]),
        ("All 3-bit words", binary_words(3)),
    ]
    for title, words in sections:
        print(title)
        print(format_report(words))
        print()


if __name__ == "__main__":
    main()

