def find_student_by_id(students_db, student_id):
    """Return the record whose 'id' matches student_id, or None."""
    for record in students_db:
        if record.get('id') == student_id:
            return record
    return None


FIELD_TYPES = {
    'id': int,
    'name': str,
    'major': str,
}


def validate_record(record):
    """Return a list of problems found in a single student record."""
    problems = []
    for field, expected in FIELD_TYPES.items():
        if field not in record:
            problems.append("missing field '{}'".format(field))
        elif not isinstance(record[field], expected):
            problems.append("field '{}' must be a {}".format(
                field,
                expected.__name__,
            ))
    return problems


def build_database(raw_records):
    """Keep only valid, non-duplicated records; report the rejected ones."""
    clean = []
    rejected = []
    for record in raw_records:
        problems = validate_record(record)
        if find_student_by_id(clean, record.get('id')) is not None:
            problems.append("duplicate id {}".format(record['id']))
        if problems:
            rejected.append((
                record,
                problems,
            ))
        else:
            clean.append(record)
    return clean, rejected


def format_student(record):
    """Render a record for the report, or a placeholder when absent."""
    if record is None:
        return 'no such student'
    return ' '.join([
        '#{}'.format(record['id']),
        record['name'],
        '({})'.format(record['major']),
    ])


def lookup_report(students_db, wanted_ids):
    lines = []
    for student_id in wanted_ids:
        found = find_student_by_id(students_db, student_id)
        lines.append('{:>4} -> {}'.format(
            student_id,
            format_student(found),
        ))
    return '\n'.join(lines)


def main():
    raw_records = [
        {'id': 1, 'name': 'Alice', 'major': 'Mathematics'},
        {'id': 2, 'name': 'Bob', 'major': 'History'},
        {'id': 3, 'name': 'Chandra', 'major': 'Physics'},
        {'id': 2, 'name': 'Bobby', 'major': 'History'},
        {'id': 'four', 'name': 'Dana', 'major': 'Biology'},
        {'id': 5, 'name': 'Elif'},
    ]
    students_db, rejected = build_database(raw_records)

    print('Accepted {} of {} records'.format(len(students_db), len(raw_records)))
    for record, problems in rejected:
        print('  rejected {!r}: {}'.format(record, ', '.join(problems)))

    print(lookup_report(students_db, [
        2,
        3,
        7,
    ]))


if __name__ == '__main__':
    main()

