DIGITS = "0123456789abcdefghijklmnopqrstuvwxyz"
DIGIT_VALUES = {ch: idx for idx, ch in enumerate(DIGITS)}

BASE_NAMES = {
    2: "binary",
    8: "octal",
    10: "decimal",
    16: "hexadecimal",
    36: "base-36",
}


def describe_base(base):
    return BASE_NAMES.get(base, "base-{}".format(base))


def _check_base(base):
    if not isinstance(base, int):
        raise TypeError("base must be an int, got {}".format(type(base).__name__))
    if base < 2 or base > 36:
        raise ValueError(
            "base must be between 2 and 36, got {}".format(base),
        )


def _digit_value(ch, base):
    value = DIGIT_VALUES.get(ch.lower())
    if value is None or value >= base:
        raise ValueError(
            "invalid digit {!r} for {}".format(ch, describe_base(base)),
        )
    return value


def base_n_to_base_10(num_str, base):
    _check_base(base)
    text = num_str.strip()
    sign = 1
    if text[:1] in ("+", "-"):
        sign = -1 if text[0] == "-" else 1
        text = text[1:]
    if not text:
        raise ValueError("no digits found in {!r}".format(num_str))
    total = 0
    for ch in text:
        total = total * base + _digit_value(ch, base)
    return sign * total


def format_row(num_str, base):
    columns = [
        num_str.strip(),
        describe_base(base),
        str(base_n_to_base_10(num_str, base)),
    ]
    return " | ".join(columns)


def digit_breakdown(num_str, base):
    text = num_str.strip().lstrip("+-")
    terms = [
        "{}*{}^{}".format(_digit_value(ch, base), base, pos)
        for pos, ch in enumerate(reversed(text))
    ]
    return " + ".join(reversed(terms))


def main():
    samples = [
        ("101", 2),
        ("A", 16),
        ("777", 8),
        ("-ff", 16),
        ("zz", 36),
        ("2024", 10),
    ]
    header = " | ".join([
        "input",
        "base name",
        "base 10",
    ])
    print(header)
    print("-" * len(header))
    for num_str, base in samples:
        print(format_row(num_str, base))
    print()
    for num_str, base in samples[:3]:
        print("{} -> {}".format(num_str, digit_breakdown(num_str, base)))


if __name__ == "__main__":
    main()

